_thumbnail','dashboard/yt_thumb_1776660520.jpg','image','Pengaturan dashboard',1,'2026-04-19 21:48:40','2026-04-19 21:48:40'),(117,'sop_permintaan_judul_hero','SOP Permintaan Informasi Publik','text','Teks dinamis untuk sop_permintaan judul_hero',1,'2026-04-21 02:02:13','2026-04-21 02:02:13'),(119,'sop_keberatan_judul_hero','SOP Penanganan Keberatan Informasi','text','Teks dinamis untuk sop_keberatan judul_hero',1,'2026-04-21 02:03:28','2026-04-21 02:03:28'),(129,'permohonan_form_schema','{\"section_title\":\"INFORMASI TUIGVJ,KJ\",\"fields\":[{\"label\":\"yhfghj\",\"type\":\"textarea\",\"name\":\"custom_yhfghj_98\"}]}','json','Skema Dynamic Form Permohonan',1,'2026-04-21 22:26:58','2026-04-22 00:05:34'),(130,'permohonan_title','Permohonan Informasi Publik','text','Pengaturan Dinamis Permohonan',1,'2026-04-21 22:26:58','2026-04-22 00:05:34'),(131,'permohonan_subtitle','Silakan lengkapi formulir di bawah ini dengan data yang benar untuk mengajukan permohonan informasi ke PPID PKTJ Tegal.','text','Pengaturan Dinamis Permohonan',1,'2026-04-21 22:26:58','2026-04-22 00:05:34'),(132,'permohonan_warning_title','Pernyataan & Pertanggungjawaban','text','Pengaturan Dinamis Permohonan',1,'2026-04-21 22:26:58','2026-04-22 00:05:34'),(133,'permohonan_warning_text','Saya menyatakan bahwa data yang diungkapkan adalah benar dan dapat dipertanggungjawabkan sesuai ketentuan yang berlaku.','text','Pengaturan Dinamis Permohonan',1,'2026-04-21 22:26:58','2026-04-22 00:05:34'),(134,'permohonan_label_title_akun','Kredensial Akun','text','Konfigurasi Inti Permohonan',1,'2026-04-21 22:26:58','2026-04-22 00:05:34'),(135,'permohonan_label_username','Username Akses','text','Konfigurasi Inti Permohonan',1,'2026-04-21 22:26:58','2026-04-22 00:05:34'),(136,'permohonan_label_email','Alamat Kontak Email','text','Konfigurasi Inti Permohonan',1,'2026-04-21 22:26:58','2026-04-22 00:05:34'),(137,'permohonan_label_password','Kata Sandi Baru','text','Konfigurasi Inti Permohonan',1,'2026-04-21 22:26:58','2026-04-22 00:05:34'),(138,'permohonan_label_password_confirmation','Ulangi Kata Sandi','text','Konfigurasi Inti Permohonan',1,'2026-04-21 22:26:58','2026-04-22 00:05:34'),(139,'permohonan_label_title_identitas','Data Identitas Pemohon','text','Konfigurasi Inti Permohonan',1,'2026-04-21 22:26:58','2026-04-22 00:05:34'),(140,'permohonan_label_nama','Nama Lengkap (Sesuai Identitas)','text','Konfigurasi Inti Permohonan',1,'2026-04-21 22:26:58','2026-04-22 00:05:34'),(141,'permohonan_label_jenis_identitas','Jenis Kartu Identitas','text','Konfigurasi Inti Permohonan',1,'2026-04-21 22:26:58','2026-04-22 00:05:34'),(142,'permohonan_label_nomor_identitas','Nomor ID Card / NIK','text','Konfigurasi Inti Permohonan',1,'2026-04-21 22:26:58','2026-04-22 00:05:34'),(143,'permohonan_label_alamat','Alamat Domisili Sekarang','text','Konfigurasi Inti Permohonan',1,'2026-04-21 22:26:58','2026-04-22 00:05:34'),(144,'permohonan_label_telepon','Nomor WhatsApp Aktif','text','Konfigurasi Inti Permohonan',1,'2026-04-21 22:26:58','2026-04-22 00:05:34'),(145,'permohonan_label_pekerjaan','Pekerjaan Utama','text','Konfigurasi Inti Permohonan',1,'2026-04-21 22:26:58','2026-04-22 00:05:34'),(146,'permohonan_label_lembaga','Nama Lembaga (Opsional)','text','Konfigurasi Inti Permohonan',1,'2026-04-21 22:26:58','2026-04-22 00:05:34'),(147,'permohonan_label_ktp','Unggah Scan/Foto Identitas Resmi','text','Konfigurasi Inti Permohonan',1,'2026-04-21 22:26:58','2026-04-22 00:05:34'),(148,'permohonan_label_title_permohonan','Rincian Informasi Yang Dimohon','text','Konfigurasi Inti Permohonan',1,'2026-04-21 22:26:58','2026-04-22 00:05:34'),(149,'permohonan_label_judul_informasi','Nama / Judul Informasi','text','Konfigurasi Inti Permohonan',1,'2026-04-21 22:26:58','2026-04-22 00:05:34'),(150,'permohonan_label_tujuan','Tujuan Penggunaan Informasi','text','Konfigurasi Inti Permohonan',1,'2026-04-21 22:26:58','2026-04-22 00:05:34'),(151,'permohonan_label_metode','Metode Perolehan Informasi','text','Konfigurasi Inti Permohonan',1,'2026-04-21 22:26:58','2026-04-22 00:05:34'),(152,'permohonan_label_pendukung','Dokumen Pendukung Tambahan','text','Konfigurasi Inti Permohonan',1,'2026-04-21 22:26:58','2026-04-22 00:05:34'),(153,'permohonan_show_pekerjaan','yes','text','Konfigurasi Inti Permohonan',1,'2026-04-21 22:26:58','2026-04-22 00:05:34'),(154,'permohonan_show_lembaga','yes','text','Konfigurasi Inti Permohonan',1,'2026-04-21 22:26:58','2026-04-22 00:05:34'),(155,'permohonan_hak_hak','<h4 style=\"text-align: center;\"><strong>HAK-HAK PEMOHON INFORMASI</strong></h4>\n<h5 style=\"text-align: center;\"><strong>Berdasarkan Undang-Undang Nomor 14 Tahun 2010 Tentang Keterbukaan Informasi Publik</strong></h5>\n<ol style=\"list-style-type: upper-roman;\">\n<li style=\"text-align: justify;\"><strong>Pemohon Informasi berhak untuk meminta seluruh informasi</strong> yang berada di <strong>Badan Publik</strong> kecuali (a) Informasi yang apabila dibuka dan diberikan kepada pemohon informasi dapat menghambat proses penegakan hukum, mengganggu kepentingan perlindungan hak atas kekayaan intelektual dan perlindungan dari persaingan usaha tidak sehat, membahayakan pertahanan dan keamanan Negara, mengungkap kekayaan alam indonesia, Merugikan pertahanan ekonomi nasional, merugikan kepentingan hubungan luar negeri, mengungkap isi akta otentik yang bersifat pribadi dan kemauan terakhir atau wasiat seseorang, mengungkap rahasia pribadi, momerandum atau surat-surat antar Badan Publik atau intra Badan Publik yang menurut sifatnya dirahasiakan kecuali atas putusan Komisi Informasi atau Pengadilan, Informasi yang tidak diungkap berdasarkan Undang-Undang b) Badan Publik juga dapat tidak memberikan informasi yang belum dikuasai atau didokumentasikan.</li>\n<li style=\"text-align: justify;\"><strong>Pastikan anda mendapat tanda bukti permohonan informasi</strong> berupa nomor pendaftaran ke petugas informasi/PPID. Bila tanda bukti permohonan informasi tidak diberikan, tanya kepada petugas informasi alasannya, mungkin permintaan informasi kurang lengkap.</li>\n<li style=\"text-align: justify;\"><strong>Permohonan Informasi berhak mendapat pemberitahuan tertulis</strong> tentang diterima atau tidaknya permohonan informasi dalam jangka waktu <strong>10 (sepuluh) hari kerja</strong> sejak diterimanya permohonan informasi oleh Badan Publik. Badan Publik dapat memperpanjang waktu untuk memberi jawabab tertulis <strong>1x7 hari kerja</strong> dalam hal; informasi yang diminta belum dikuasai/didokumentasikan/belum dapat diputuskan apakah informasi yang diminta termasuk informasi yang dikecualikan atau tidak.</li>\n<li style=\"text-align: justify;\"><strong>Biaya yang dikenakan atas salinan informasi</strong> dibebankan kepada pemohon informasi.</li>\n<li style=\"text-align: justify;\"><strong>Apabila Pemohon Informasi tidak puas dengan Keputusan Pimpinan Badan Publik</strong> (misal: menolak permintaan anda atau memberikan hanya sebagian yang diminta), maka Pemohon Informasi dapat mengajukan keberatan kepada atasan PPID dalam jangka waktu <strong>30 (tiga puluh) hari kerja</strong> sejak permohonan informasi ditolak/ditemukannya alasan keberatan lainnya. Atasan PPID wajib memberikan tanggapan tertulis atas keberatan yang diajukan Pemohon Informasi selambat-lambatnya <strong>30 (tiga puluh) hari kerja</strong> sejak diterimanya/dicatatnya pengajuan keberatan dalam register keberatan.</li>\n<li style=\"text-align: justify;\"><strong>Apabila Pemohon Informasi tidak puas dengan keputusan Atasan PPID</strong>, maka Pemohon Informasi dapat mengajukan keberatan kepada <strong>Komisi Informasi</strong> dalam jangka waktu <strong>14 (empat belas) hari kerja</strong> sejak diterimanya keputusan Atasan PPID oleh Pemohon Informasi Publik.</li>\n</ol>','text','Pengaturan Dinamis Permohonan',1,'2026-04-21 23:41:28','2026-04-22 00:05:34'),(158,'layanan_daftar_judul_hero','Daftar Informasi Publik','text','Teks dinamis untuk layanan_daftar judul_hero',1,'2026-04-23 00:06:01','2026-04-23 00:06:01'),(159,'layanan_daftar_tagline_hero','Pejabat Pengelola Informasi dan Dokumentasi','text','Teks dinamis untuk layanan_daftar tagline_hero',1,'2026-04-23 00:06:01','2026-04-23 00:06:01'),(169,'laporan_layanan_judul_hero','Laporan Pelayanan Informasi','text','Teks dinamis untuk laporan_layanan judul_hero',1,'2026-04-28 19:21:59','2026-04-28 19:21:59'),(173,'laporan_layanan_file_laporan','1779281908_laporan_layanan_file_laporan.pdf','file','File untuk laporan_layanan file_laporan',1,'2026-04-28 19:21:59','2026-05-20 05:58:28'),(174,'laporan_akses_judul_hero','Laporan Akses Informasi','text','Teks dinamis untuk laporan_akses judul_hero',1,'2026-04-28 19:25:24','2026-04-28 19:25:24'),(178,'laporan_akses_file_laporan','1779282710_laporan_akses_file_laporan.pdf','file','File untuk laporan_akses file_laporan',1,'2026-04-28 19:25:24','2026-05-20 06:11:50'),(179,'laporan_survey_judul_hero','Laporan Survey Kepuasan','text','Teks dinamis untuk laporan_survey judul_hero',1,'2026-04-28 19:28:34','2026-04-28 19:28:34'),(183,'laporan_survey_file_laporan','1779282850_laporan_survey_file_laporan.pdf','file','File untuk laporan_survey file_laporan',1,'2026-04-28 19:28:35','2026-05-20 06:14:10'),(187,'sop_sengketa_judul_hero','SOP Penyelesaian Sengketa Informasi','text','Teks dinamis untuk sop_sengketa judul_hero',1,'2026-04-28 21:13:17','2026-04-28 21:13:17'),(192,'maklumat_pelayanan_judul_hero','Maklumat Pelayanan','text','Teks dinamis untuk maklumat_pelayanan judul_hero',1,'2026-05-04 02:09:24','2026-05-04 02:09:24'),(193,'maklumat_pelayanan_tagline_hero','Komitmen Pelayanan Informasi Publik Prima, Cepat, dan Transparan','text','Pengaturan resmi maklumat_pelayanan_tagline_hero',1,'2026-05-04 02:09:24','2026-08-30 20:20:03'),(194,'maklumat_pelayanan_judul_maklumat','Maklumat Pelayanan PPID PKTJ Tegal','text','Pengaturan resmi maklumat_pelayanan_judul_maklumat',1,'2026-05-04 02:09:24','2026-08-30 20:20:03'),(195,'maklumat_pelayanan_isi_maklumat','<p>Dengan ini kami menyatakan sanggup menyelenggarakan pelayanan informasi publik sesuai standar pelayanan yang telah ditetapkan, memberikan kemudahan akses informasi secara cepat, tepat waktu, biaya ringan, dan proporsional, serta siap menerima sanksi sesuai ketentuan peraturan perundang-undangan apabila pelayanan yang diberikan tidak sesuai dengan standar yang dijanjikan.</p>','text','Pengaturan resmi maklumat_pelayanan_isi_maklumat',1,'2026-05-04 02:09:24','2026-08-30 20:20:03'),(196,'laporan_layanan_tagline_hero','Akuntabilitas dan Kinerja Layanan Informasi Publik','text','Pengaturan resmi laporan_layanan_tagline_hero',1,'2026-05-04 02:11:01','2026-08-30 20:20:03'),(197,'laporan_layanan_tahun_laporan','2026','text','Teks dinamis untuk laporan_layanan tahun_laporan',1,'2026-05-04 02:11:01','2026-05-04 02:11:01'),(198,'laporan_layanan_ringkasan_eksekutif','<p>Laporan Tahunan Pelayanan Informasi Publik PPID Politeknik Keselamatan Transportasi Jalan Tegal memuat rekapitulasi jumlah permohonan informasi masuk, jangka waktu pemenuhan, jumlah permohonan yang dikabulkan/ditolak, serta pengajuan keberatan selama periode tahun anggaran berjalan.</p>','text','Pengaturan resmi laporan_layanan_ringkasan_eksekutif',1,'2026-05-04 02:11:01','2026-08-30 20:20:03'),(199,'laporan_akses_tagline_hero','Statistik dan Trafik Keterbukaan Informasi Publik','text','Pengaturan resmi laporan_akses_tagline_hero',1,'2026-05-04 18:36:26','2026-08-30 20:20:03'),(200,'laporan_akses_tahun_laporan','2026','text','Teks dinamis untuk laporan_akses tahun_laporan',1,'2026-05-04 18:36:26','2026-05-04 18:36:26'),(201,'laporan_akses_ringkasan_eksekutif','<p>Laporan Akses Informasi menyajikan data statistik pengunjung portal website PPID, volume pengunduhan dokumen terbuka, dan tren minat masyarakat terhadap informasi pendidikan vokasi transportasi jalan.</p>','text','Pengaturan resmi laporan_akses_ringkasan_eksekutif',1,'2026-05-04 18:36:26','2026-08-30 20:20:03'),(202,'sop_permintaan_tagline_hero','Alur dan Prosedur Permohonan Informasi Publik Resmi','text','Pengaturan resmi sop_permintaan_tagline_hero',1,'2026-05-04 18:39:22','2026-08-30 20:20:03'),(203,'sop_permintaan_youtube_link','https://youtu.be/yZu8YiDyaro?si=hNu33jnfqQB-d1vT','text','Teks dinamis untuk sop_permintaan youtube_link',1,'2026-05-04 18:39:22','2026-05-04 18:39:22'),(204,'sop_permintaan_konten','<p>Pemohon informasi dapat mengajukan permohonan secara online melalui formulir portal PPID PKTJ atau secara luring di meja layanan PPID dengan melampirkan kartu identitas resmi (KTP/SIM/Paspor). Petugas akan memproses dan memberikan pemberitahuan tertulis paling lambat 10 (sepuluh) hari kerja sejak permohonan dinyatakan lengkap.</p>','text','Pengaturan resmi sop_permintaan_konten',1,'2026-05-04 18:39:22','2026-08-30 20:20:03'),(205,'sop_permintaan_gambar_sop','1777945162_sop_permintaan_gambar_sop.png','file','File untuk sop_permintaan gambar_sop',1,'2026-05-04 18:39:22','2026-05-04 18:39:22'),(206,'sop_permintaan_gambar_proses','1777945162_sop_permintaan_gambar_proses.png','file','File untuk sop_permintaan gambar_proses',1,'2026-05-04 18:39:22','2026-05-04 18:39:22'),(207,'sop_keberatan_tagline_hero','Mekanisme Pengajuan dan Penanganan Keberatan Informasi','text','Pengaturan resmi sop_keberatan_tagline_hero',1,'2026-05-04 23:27:02','2026-08-30 20:20:03'),(208,'sop_keberatan_konten','<p>Pemohon berhak mengajukan keberatan kepada Atasan PPID apabila permohonan informasi ditolak, tidak ditanggapi dalam batas waktu yang ditentukan, atau dikenakan biaya yang tidak wajar. Tanggapan atas keberatan akan diberikan secara tertulis dalam jangka waktu paling lambat 30 (tiga puluh) hari kerja.</p>','text','Pengaturan resmi sop_keberatan_konten',1,'2026-05-04 23:27:02','2026-08-30 20:20:03'),(209,'sop_keberatan_gambar_sop','1777962422_sop_keberatan_gambar_sop.png','file','File untuk sop_keberatan gambar_sop',1,'2026-05-04 23:27:02','2026-05-04 23:27:02'),(210,'sop_keberatan_gambar_proses','1777962422_sop_keberatan_gambar_proses.png','file','File untuk sop_keberatan gambar_proses',1,'2026-05-04 23:27:02','2026-05-04 23:27:02'),(211,'laporan_survey_tagline_hero','Indeks Kepuasan Masyarakat (IKM) Pelayanan Informasi','text','Pengaturan resmi laporan_survey_tagline_hero',1,'2026-05-04 23:28:35','2026-08-30 20:20:03'),(212,'laporan_survey_tahun_laporan','2026','text','Teks dinamis untuk laporan_survey tahun_laporan',1,'2026-05-04 23:28:35','2026-05-04 23:28:35'),(213,'laporan_survey_ringkasan_eksekutif','<p>Hasil survei kepuasan masyarakat terhadap mutu pelayanan informasi PPID PKTJ menunjukkan tingkat kepuasan berpredikat SANGAT BAIK, mencakup aspek transparansi, kecepatan respon petugas, kemudahan akses fasilitas digital, dan keramahan pelayanan ramah disabilitas.</p>','text','Pengaturan resmi laporan_survey_ringkasan_eksekutif',1,'2026-05-04 23:28:35','2026-08-30 20:20:03'),(214,'sop_sengketa_tagline_hero','Prosedur Penyelesaian Sengketa Informasi di Komisi Informasi','text','Pengaturan resmi sop_sengketa_tagline_hero',1,'2026-05-05 00:29:51','2026-08-30 20:20:03'),(215,'sop_sengketa_konten','<p>Apabila tanggapan atas keberatan belum memuaskan pemohon, pemohon informasi publik dapat mengajukan permohonan penyelesaian sengketa informasi kepada Komisi Informasi Pusat dalam waktu paling lambat 14 (empat belas) hari kerja sejak diterimanya tanggapan Atasan PPID.</p>','text','Pengaturan resmi sop_sengketa_konten',1,'2026-05-05 00:29:51','2026-08-30 20:20:03'),(216,'sop_sengketa_gambar_sop','1777966191_sop_sengketa_gambar_sop.png','file','File untuk sop_sengketa gambar_sop',1,'2026-05-05 00:29:51','2026-05-05 00:29:51'),(217,'sop_sengketa_gambar_proses','1777966191_sop_sengketa_gambar_proses.jpeg','file','File untuk sop_sengketa gambar_proses',1,'2026-05-05 00:29:51','2026-05-05 00:29:51'),(218,'sop_penetapan_judul_hero','SOP Penetapan dan Pemutakhiran DIP','text','Teks dinamis untuk sop_penetapan judul_hero',1,'2026-05-05 00:32:21','2026-05-05 00:32:21'),(219,'sop_penetapan_tagline_hero','Tata Kelola Pemutakhiran Daftar Informasi Publik (DIP)','text','Pengaturan resmi sop_penetapan_tagline_hero',1,'2026-05-05 00:32:21','2026-08-30 20:20:03'),(220,'sop_penetapan_konten','<p>Standar operasional prosedur pengumpulan, penelaahan, dan pemutakhiran berkala atas Daftar Informasi Publik (DIP) dan Daftar Informasi yang Dikecualikan (DIK) yang melibatkan seluruh unit kerja, program studi, dan bagian di lingkungan PKTJ Tegal.</p>','text','Pengaturan resmi sop_penetapan_konten',1,'2026-05-05 00:32:21','2026-08-30 20:20:03'),(221,'sop_penetapan_gambar_sop','1777966341_sop_penetapan_gambar_sop.png','file','File untuk sop_penetapan gambar_sop',1,'2026-05-05 00:32:21','2026-05-05 00:32:21'),(222,'sop_penetapan_gambar_proses','1777966341_sop_penetapan_gambar_proses.jpg','file','File untuk sop_penetapan gambar_proses',1,'2026-05-05 00:32:21','2026-05-05 00:32:21'),(223,'sop_pengujian_judul_hero','SOP Pengujian Konsekuensi','text','Teks dinamis untuk sop_pengujian judul_hero',1,'2026-05-05 01:14:12','2026-05-05 01:14:12'),(224,'sop_pengujian_tagline_hero','Mekanisme Pengujian Konsekuensi Informasi Dikecualikan','text','Pengaturan resmi sop_pengujian_tagline_hero',1,'2026-05-05 01:14:12','2026-08-30 20:20:03'),(225,'sop_pengujian_konten','<p>Tata cara pengujian konsekuensi dengan seksama dan penuh kehati-hatian sebelum menyatakan suatu informasi publik bersifat rahasia/dikecualikan berdasarkan Pasal 17 Undang-Undang Nomor 14 Tahun 2008.</p>','text','Pengaturan resmi sop_pengujian_konten',1,'2026-05-05 01:14:12','2026-08-30 20:20:03'),(226,'sop_pengujian_gambar_sop','1777968852_sop_pengujian_gambar_sop.png','file','File untuk sop_pengujian gambar_sop',1,'2026-05-05 01:14:12','2026-05-05 01:14:12'),(227,'sop_pengujian_gambar_proses','1777968852_sop_pengujian_gambar_proses.PNG','file','File untuk sop_pengujian gambar_proses',1,'2026-05-05 01:14:12','2026-05-05 01:14:12'),(228,'sop_pendokumentasian_judul_hero','SOP Pendokumentasian Informasi Publik','text','Teks dinamis untuk sop_pendokumentasian judul_hero',1,'2026-05-05 01:17:12','2026-05-05 01:17:12'),(229,'sop_pendokumentasian_tagline_hero','Tata Kelola Pengarsipan dan Repositori Digital Informasi','text','Pengaturan resmi sop_pendokumentasian_tagline_hero',1,'2026-05-05 01:17:12','2026-08-30 20:20:03'),(230,'sop_pendokumentasian_konten','<p>Standar pengelolaan, penyimpanan fisik, dan pengamanan sistem basis data arsip informasi publik agar terhindar dari kerusakan, kehilangan, dan perubahan tidak sah.</p>','text','Pengaturan resmi sop_pendokumentasian_konten',1,'2026-05-05 01:17:12','2026-08-30 20:20:03'),(231,'sop_pendokumentasian_gambar_sop','1777969032_sop_pendokumentasian_gambar_sop.png','file','File untuk sop_pendokumentasian gambar_sop',1,'2026-05-05 01:17:12','2026-05-05 01:17:12'),(232,'sop_pendokumentasian_gambar_proses','1777969032_sop_pendokumentasian_gambar_proses.png','file','File untuk sop_pendokumentasian gambar_proses',1,'2026-05-05 01:17:12','2026-05-05 01:17:12'),(233,'maklumat_pelayanan_judul_standar','Standar Biaya Pelayanan Informasi','text','Pengaturan resmi maklumat_pelayanan_judul_standar',1,'2026-05-05 20:44:17','2026-08-30 20:20:03'),(234,'maklumat_pelayanan_isi_standar','<p>Penyediaan layanan informasi publik di lingkungan Politeknik Keselamatan Transportasi Jalan (PKTJ) Tegal <strong>TIDAK DIPUNGUT BIAYA (GRATIS / Rp 0,-)</strong> untuk seluruh dokumen dalam format digital/softcopy. Apabila pemohon menghendaki salinan fisik/hardcopy atau penggandaan khusus, biaya penggandaan dan pengiriman dibebankan kepada pemohon sesuai ketentuan perundang-undangan.</p>','text','Pengaturan resmi maklumat_pelayanan_isi_standar',1,'2026-05-05 20:44:17','2026-08-30 20:20:03'),(235,'maklumat_pelayanan_gambar_maklumat','1778039057_maklumat_pelayanan_gambar_maklumat.png','file','File untuk maklumat_pelayanan gambar_maklumat',1,'2026-05-05 20:44:17','2026-05-05 20:44:17'),(236,'maklumat_pelayanan_gambar_standar','1778039057_maklumat_pelayanan_gambar_standar.png','file','File untuk maklumat_pelayanan gambar_standar',1,'2026-05-05 20:44:17','2026-05-05 20:44:17'),(237,'premium_view_enabled','1','text',NULL,1,'2026-05-05 20:48:56','2026-05-05 20:48:56'),(238,'layanan_daftar_hero_image','1778143218_layanan_daftar_hero_image.png','file','File untuk layanan_daftar hero_image',1,'2026-05-07 01:40:20','2026-05-07 01:40:20'),(239,'profil_youtube_link','','text',NULL,1,'2026-05-11 01:05:02','2026-05-11 01:05:02'),(240,'tugas_youtube_link','','text',NULL,1,'2026-05-15 23:03:50','2026-05-15 23:03:50'),(241,'regulasi_youtube_link','','text',NULL,1,'2026-05-16 00:01:05','2026-05-16 00:01:05'),(242,'visi_youtube_link','','text',NULL,1,'2026-05-16 00:19:42','2026-05-16 00:19:42'),(243,'struktur_youtube_link','','text',NULL,1,'2026-05-20 16:10:09','2026-05-20 16:10:09'),(244,'kontak_youtube_link','https://www.youtube.com/channel/UC9BbdnU-cczfaZ5FHulYPZA','text',NULL,1,'2026-05-20 16:13:28','2026-07-13 00:48:51'),(245,'kontak_facebook_link','https://www.facebook.com/PKTJTegal/','text','Pengaturan link sosial media kontak_facebook_link',1,'2026-07-13 00:48:51','2026-07-13 00:48:51'),(246,'kontak_instagram_link','https://www.instagram.com/pktj_tegal/','text','Pengaturan link sosial media kontak_instagram_link',1,'2026-07-13 00:48:51','2026-07-13 00:48:51'),(247,'kontak_twitter_link','https://x.com/pktjtegal','text','Pengaturan link sosial media kontak_twitter_link',1,'2026-07-13 00:48:51','2026-07-13 00:48:51'),(248,'kontak_linktree_link','https://linktr.ee/pktj_tegal','text','Pengaturan link sosial media kontak_linktree_link',1,'2026-07-13 00:48:52','2026-07-13 00:48:52'),(249,'kontak_whatsapp_link','https://api.whatsapp.com/send/?phone=6281234700230&text&type=phone_number&app_absent=0','text','Pengaturan link sosial media kontak_whatsapp_link',1,'2026-07-13 00:48:52','2026-07-13 00:48:52'),(250,'kontak_tiktok_link','https://www.tiktok.com/@pktj_tegal','text','Pengaturan link sosial media kontak_tiktok_link',1,'2026-07-13 00:48:52','2026-07-13 00:48:52'),(251,'kontak_website_l