/*!40000 ALTER TABLE `faqs` DISABLE KEYS */;
INSERT INTO `faqs` VALUES (1,'Apa itu PPID?','<p>PPID adalah singkatan dari Pejabat Pengelola Informasi dan Dokumentasi. PPID adalah pejabat yang bertanggung jawab di bidang penyimpanan, pendokumentasian, penyediaan, dan/atau pelayanan informasi di badan publik sesuai dengan Undang-Undang Nomor 14 Tahun 2008 tentang Keterbukaan Informasi Publik.<br><br><br><br>huigyhjhgbkjjjkgjbjhbg,hjk ang</p>',1,0,'2026-03-27 01:16:12','2026-04-19 20:58:24'),(2,'Apa tugas PPID?','<p>PPID bertugas untuk menyimpan, mendokumentasikan, menyediakan, dan/atau melayani permintaan informasi publik; membuat dan mengembangkan sistem informasi dan dokumentasi; mengkoordinasikan pengumpulan bahan informasi dan dokumentasi; serta menyediakan informasi dan dokumentasi yang diperlukan oleh masyarakat.</p>\r\n<p>&nbsp;</p>\r\n<p><img src=\"http://ppid.pktj.ac.id/storage/editor_uploads/1777460231_69f1e4078c189.png\" alt=\"\" width=\"149\" height=\"200\"></p>',1,0,'2026-03-27 01:16:12','2026-04-29 03:57:29'),(3,'Bagaimana cara mengajukan permintaan informasi?','<p>Permintaan informasi dapat diajukan melalui beberapa cara:</p><ul><li>Mengisi formulir permohonan informasi online di website PPID</li><li>Datang langsung ke kantor PPID dengan membawa identitas diri</li><li>Mengirim surat permohonan ke alamat PPID</li><li>Menghubungi hotline PPID untuk informasi awal</li></ul>',1,0,'2026-03-27 01:16:12','2026-03-27 01:22:07'),(4,'Berapa lama waktu penyelesaian permintaan informasi?','<p>Berdasarkan Undang-Undang KIP, waktu penyelesaian permintaan informasi adalah:</p><ul><li>Maksimal 10 hari kerja untuk informasi yang tersedia dan dapat langsung diberikan</li><li>Maksimal 30 hari kerja untuk informasi yang perlu pencarian dan/atau penyiapan</li><li>Dapat diperpanjang maksimal 30 hari kerja dengan pemberitahuan tertulis</li></ul>',1,0,'2026-03-27 01:16:12','2026-03-27 01:22:07'),(5,'Apakah ada biaya untuk mendapatkan informasi?','<p>Untuk permintaan informasi yang berkaitan dengan kepentingan umum, PPID memberikan informasi tanpa biaya. Namun, untuk permintaan informasi yang memerlukan penggandaan atau pengiriman dokumen, pemohon informasi dapat dikenakan biaya sesuai dengan Standar Biaya Pelayanan Informasi Publik yang telah ditetapkan.</p><p>Biaya yang mungkin dikenakan meliputi:</p><ul><li>Biaya penggandaan dokumen</li><li>Biaya pengiriman dokumen</li><li>Biaya penyediaan media penyimpanan</li></ul>',1,0,'2026-03-27 01:16:12','2026-03-27 01:22:07'),(6,'Informasi apa saja yang tidak dapat diakses?','<p>Informasi yang dikecualikan dari keterbukaan informasi publik meliputi:</p>\r\n<ul>\r\n<li>Informasi yang dapat membahayakan negara</li>\r\n<li>Informasi yang berkaitan dengan rahasia dagang</li>\r\n<li>Informasi yang berkaitan dengan hak kekayaan intelektual</li>\r\n<li>Informasi yang berkaitan dengan data pribadi</li>\r\n<li>Informasi yang masih dalam proses pengolahan</li>\r\n</ul>\r\n<p>Pengecualian informasi harus berdasarkan alasan yang sah dan tidak bersifat mutlak.<br><br><br>g87g6ydtujfdutj</p>',1,0,'2026-03-27 01:16:12','2026-05-20 16:16:21'),(7,'Apa yang harus dilakukan jika permintaan informasi ditolak?','<p>Jika permintaan informasi ditolak, pemohon informasi dapat:</p><ul><li>Mengajukan keberatan kepada PPID dalam waktu 30 hari kerja</li><li>Mengajukan sengketa informasi ke Komisi Informasi</li><li>Mengajukan gugatan ke Pengadilan Tata Usaha Negara</li></ul><p>Proses keberatan dan sengketa informasi diatur dalam Undang-Undang KIP dan peraturan pelaksanaannya.</p>',1,0,'2026-03-27 01:16:12','2026-03-27 01:22:07'),(8,'Kapan jam kerja PPID?','<p>PPID PKTJ melayani permintaan informasi pada hari dan jam kerja sebagai berikut:</p><ul><li><strong>Hari kerja:</strong> Senin - Jumat</li><li><strong>Jam kerja:</strong> 08:00 - 16:00 WIB</li><li><strong>Istirahat:</strong> 12:00 - 13:00 WIB</li><li><strong>Hari libur:</strong> Sabtu, Minggu, dan hari libur nasional</li></ul><p>Untuk keadaan darurat, dapat menghubungi hotline PPID 24 jam.</p>',1,0,'2026-03-27 01:16:12','2026-03-27 01:22:07'),(9,'Bagaimana cara menghubungi PPID?','<p>PPID PKTJ dapat dihubungi melalui berbagai kanal:</p><p><strong>Alamat Kantor:</strong> Jl. Medan Merdeka Barat No. 8, Jakarta Pusat 10110, Indonesia</p><p><strong>Kontak:</strong></p><ul><li>Telp: (021) 3847790</li><li>Fax: (021) 3847791</li><li>Email: ppid@pktj.dephub.go.id</li></ul>',1,0,'2026-03-27 01:16:12','2026-03-27 01:22:07'),(10,'Apa saja jenis informasi publik yang tersedia?','<p>Jenis informasi publik yang tersedia di PPID PKTJ meliputi:</p><ul><li><strong>Informasi Berkala:</strong> Laporan tahunan, laporan keuangan, profil organisasi</li><li><strong>Informasi Serta Merta:</strong> Informasi yang berkaitan dengan hajat hidup orang banyak</li><li><strong>Informasi Setiap Saat:</strong> Daftar informasi publik, maklumat pelayanan</li><li><strong>Informasi Dikecualikan:</strong> Informasi yang dikecualikan berdasarkan alasan yang sah</li></ul>',1,0,'2026-03-27 01:16:12','2026-03-27 01:22:07');
/*!40000 ALTER TABLE `faqs` ENABLE KEYS */;
UNLOCK TABLES;

