INSERT INTO `informasi_dikecualikans` VALUES (1,'Daftar Aplikasi Internal PKTJ dan Monitoring Aksesibilitas','Daftar lengkap aplikasi/sistem informasi yang digunakan secara internal di lingkungan PKTJ meliputi: Website PKTJ, SIAKAD, SIMATA, Seleksi Penerimaan Calon Taruna, E-Library, Repository, Katalog Online Buku, Aplikasi Jurnal, Aplikasi Rekap SPPD, Aplikasi Dokumen Keuangan, Aplikasi Ujian Berbasis Computer, Tracer Study, dan LIMS. Termasuk laporan monitoring kondisi dan aksesibilitas aplikasi.','2025-01-01',NULL,NULL,NULL,'sesuai retensi arsip','Unit Kerja di lingkungan PKTJ','storage/informasi/dikecualikan/Preview.Daftar Aplikasi Internal PKTJ dan Monitoring Aksesibilitas','Dokumen','-','PDF',1,0,'2024-12-31 17:00:00','2024-12-31 17:00:00',1),(2,'Data Taruna Aktif Tahun Akademik 2025/2026  - Ganjil','Tahun Akademik 2025/2026 Semester Ganjil, tercatat data taruna aktif yang dikelompokkan berdasarkan Angkatan, Tahun Masuk, Tahun Lulus, Program Studi, Kelas, Jalur Penerimaan, serta Jenis Kelamin','2025-01-01',NULL,NULL,NULL,'5 (lima) tahun','Tim Administrasi Ketarunaan dan Alumni','storage/informasi/dikecualikan/Data Taruna Tahun Akademik 20252026 Ganjil (Informasi Publik).pdf','Dokumen','-','PDF',1,0,'2024-12-31 17:00:00','2024-12-31 17:00:00',1),(3,'MCU Siswa Diklat SPAU tahun 2025','Kegiatan Medical Check Up bagi Siswa Diklat SPAU','2025-01-01',NULL,NULL,NULL,'5 tahun','Nakes Unit Kesehatan','storage/informasi/dikecualikan/MCU Siswa Diklat SPAU tahun 2025 (Informasi Publik)','Dokumen','-','PDF',1,0,'2024-12-31 17:00:00','2024-12-31 17:00:00',1);
