INSERT INTO `informasi_setiapsaats` VALUES (1,'Keputusan Penetapan & Usulan Daftar Informasi Publik (DIP) dan Daftar Informasi Dikecualikan (DIK) PKTJ Tahun 2026','<p>Dokumen penetapan dan tabel klasifikasi lengkap Daftar Informasi Publik (DIP) dan Daftar Informasi Dikecualikan (DIK) di lingkungan Politeknik Keselamatan Transportasi Jalan Tegal Tahun 2026.</p>',NULL,'storage/dokumen/G1.pdf','20251210221658Usulan DIP dan DIK 2026 PKTJ.pdf','483 KB','pdf',1,0,'2026-08-31 18:58:26','2026-08-31 18:58:26',1),(2,'Laporan Posisi BMN & Salinan Surat Rekomendasi Penghapusan BMN ke KPKNL Bangunan Gedung (Tersensor Sesuai UU KIP)','<p>Laporan posisi aset dan inventaris Barang Milik Negara (BMN) PKTJ Tegal, serta salinan surat permohonan persetujuan penghapusan BMN gedung ke KPKNL Tegal yang telah disensor sesuai UU KIP.</p>',NULL,'storage/dokumen/Laporan_BMN.pdf','Salinan 202507231513390_Surat Rekomendasi Penghapusan BMN ke KPKNL Bangunan Gedung_TERSENSOR.pdf','1,5 MB','pdf',1,0,'2026-08-31 18:58:26','2026-08-31 18:58:26',1),(3,'Buku Register Agenda Surat Masuk dan Surat Keluar Kedinasan PKTJ Tahun 2023-2026','<p>Rekapitulasi pencatatan agenda surat masuk dan surat keluar kedinasan melalui sistem persuratan tata naskah dinas elektronik (Srikandi Kemenhub) PKTJ Tegal.</p>',NULL,'storage/dokumen/Surat_Masuk_Keluar.pdf','Buku Register Surat Masuk & Keluar 2023-2026.pdf','2,4 MB','pdf',1,0,'2026-08-31 18:58:26','2026-08-31 18:58:26',1),(4,'Buku Pedoman Standar Operasional Prosedur (SOP) Pelayanan Publik Terpadu PKTJ Tegal','<p>Kumpulan pedoman Standar Operasional Prosedur (SOP) teknis penyelenggaraan pelayanan administrasi akademik, ketarunaan, sarana prasarana, dan layanan informasi publik terpadu PKTJ Tegal.</p>',NULL,'storage/dokumen/G2.pdf','Pedoman SOP Pelayanan PKTJ.pdf','1,8 MB','pdf',1,0,'2026-08-31 18:58:26','2026-08-31 18:58:26',1);
