INSERT INTO `pejabats` VALUES (1,'Dr. Ir. Bambang Istiyanto, S.SiT., M.T., IPU','19730514 199803 1 002','DIREKTUR',NULL,'images/pejabat/Bambang Istiyanto.png',160,240,390,'top center','14px','Alamat kantor Kampus I Jl. Perintis Kemerdekaan No. 17 / Kampus II Jl. Abdul Syukur No. 17, Kota Tegal 52125 Telp. (0283) 351061. Menempuh pendidikan D4/S1 Terapan di bidang Transportasi Darat di Sekolah Tinggi Transportasi Darat (STTD), magister (S2) Teknik Sipil / Transportasi di Institut Teknologi Bandung (ITB), Profesi Insinyur Profesional Utama (IPU) di Persatuan Insinyur Indonesia (PII), dan program Doktoral (S3) Teknik Sipil di Universitas Islam Sultan Agung (UNISSULA) Semarang. Pernah menjabat sebagai Kepala Subdirektorat Rekayasa dan Keselamatan Jalan Ditjen Perhubungan Darat, Kepala Bagian Administrasi Akademik dan Ketarunaan PKTJ Tegal, Wakil Direktur I Politeknik Transportasi Darat Bali (POLTRADA Bali), dan saat ini menjabat sebagai Direktur Politeknik Keselamatan Transportasi Jalan (PKTJ) Tegal. Beliau telah dianugerahi tanda kehormatan Satyalancana Karya Satya 20 Tahun dan Satyalancana Karya Satya 10 Tahun oleh Presiden Republik Indonesia.','[\"S3 - Doktor (Dr.) Teknik Sipil, Universitas Islam Sultan Agung (UNISSULA) Semarang\", \"Profesi Insinyur - Insinyur Profesional Utama (IPU), Persatuan Insinyur Indonesia (PII)\", \"S2 - Magister Teknik (M.T.) Sipil / Transportasi, Institut Teknologi Bandung (ITB)\", \"D4 / S1 Terapan - Sarjana Sains Terapan Transportasi (S.SiT), Sekolah Tinggi Transportasi Darat (STTD)\", \"Pendidikan dan Pelatihan Penjenjangan Kepemimpinan Administrator (PIM Tingkat III)\"]','[\"Direktur Politeknik Keselamatan Transportasi Jalan (PKTJ) Tegal (2024 - Sekarang)\", \"Wakil Direktur I Politeknik Transportasi Darat Bali (POLTRADA Bali)\", \"Kepala Bagian Administrasi Akademik dan Ketarunaan PKTJ Tegal\", \"Kepala Subdirektorat Rekayasa dan Keselamatan Jalan Ditjen Hubdat\"]','[\"Satyalancana Karya Satya 20 Tahun Presiden RI\", \"Satyalancana Karya Satya 10 Tahun Presiden RI\"]',NULL,NULL,NULL,'2025/2026',1,1,'2026-08-31 20:12:26','2026-09-02 20:01:05'),(2,'Edi Purwanto, A.TD, M.T.','19700918 199803 1 001','WAKIL DIREKTUR I',NULL,'images/pejabat/Edi Purwanto.png',160,240,390,'top center','14px','Alamat kantor Kampus I Jl. Perintis Kemerdekaan No. 17 / Kampus II Jl. Abdul Syukur No. 17, Kota Tegal 52125 Telp. (0283) 351061. Menempuh pendidikan D3 di bidang Transportasi Darat di Sekolah Tinggi Transportasi Darat (STTD) dan magister (S2) Teknik Sipil / Sistem Rekayasa Transportasi di Universitas Diponegoro (UNDIP). Pernah menjabat sebagai Dosen Lektor Bidang Manajemen & Rekayasa Keselamatan Transportasi Jalan, Ketua Program Studi Diploma IV Rekayasa Sistem Transportasi Jalan (RSTJ), dan saat ini menjabat sebagai Wakil Direktur I (Bidang Akademik) Politeknik Keselamatan Transportasi Jalan (PKTJ) Tegal. Beliau telah dianugerahi tanda kehormatan Satyalancana Karya Satya 20 Tahun dan Satyalancana Karya Satya 10 Tahun oleh Presiden Republik Indonesia.','[\"S2 - Magister Teknik Sipil / Sistem Rekayasa Transportasi, Universitas Diponegoro (UNDIP)\", \"D3 - Ahli Transportasi Darat (A.TD), Sekolah Tinggi Transportasi Darat (STTD)\", \"Pelatihan Pendidik Perguruan Tinggi & Auditor Mutu Internal\"]','[\"Wakil Direktur I (Bidang Akademik) PKTJ Tegal (2024 - Sekarang)\", \"Ketua Program Studi Diploma IV Rekayasa Sistem Transportasi Jalan (RSTJ) PKTJ\", \"Dosen Lektor Bidang Manajemen & Rekayasa Keselamatan Transportasi Jalan\"]','[\"Satyalancana Karya Satya 20 Tahun Presiden RI\", \"Satyalancana Karya Satya 10 Tahun Presiden RI\"]',NULL,NULL,NULL,'2025/2026',2,1,'2026-08-31 20:12:26','2026-09-02 20:01:05'),(3,'Sugianto, ATD, MM.','19660601 199103 1 004','WAKIL DIREKTUR II',NULL,'images/pejabat/Sugianto.png',160,240,390,'top center','14px','Alamat kantor Kampus I Jl. Perintis Kemerdekaan No. 17 / Kampus II Jl. Abdul Syukur No. 17, Kota Tegal 52125 Telp. (0283) 351061. Menempuh pendidikan D3 di bidang Transportasi Darat di Sekolah Tinggi Transportasi Darat (STTD) dan magister (S2) Manajemen di Universitas Jenderal Soedirman. Pernah menjabat sebagai Kepala Bagian Rencana Ditjen Perhubungan Darat, Kepala Balai Teknik Perkeretaapian Kelas II Sumatera Bagian Selatan, Wakil Direktur I Bidang Akademik PKTJ Tegal (2022-2024), dan saat ini menjabat sebagai Wakil Direktur II (Bidang Keuangan, Umum dan Kerja Sama) Politeknik Keselamatan Transportasi Jalan (PKTJ) Tegal. Beliau telah dianugerahi tanda kehormatan Satyalancana Karya Satya 30 Tahun dan Satyalancana Karya Satya 20 Tahun oleh Presiden Republik Indonesia.','[\"S2 - Magister Manajemen (MM), Universitas Jenderal Soedirman\", \"D3 - Ahli Transportasi Darat (ATD), Sekolah Tinggi Transportasi Darat (STTD)\", \"Pelatihan Kepemimpinan Administrator (PIM Tingkat III)\"]','[\"Wakil Direktur II (Bidang Keuangan, Umum dan Kerja Sama) PKTJ (2024 - Sekarang)\", \"Wakil Direktur I Bidang Akademik PKTJ (2022 - 2024)\", \"Kepala Balai Teknik Perkeretaapian Kelas II Sumatera Bagian Selatan\", \"Kepala Bagian Rencana Ditjen Perhubungan Darat\"]','[\"Satyalancana Karya Satya 30 Tahun Presiden RI\", \"Satyalancana Karya Satya 20 Tahun Presiden RI\"]',NULL,NULL,NULL,'2025/2026',3,1,'2026-08-31 20:12:26','2026-09-02 20:01:05'),(4,'Dr. Setya Wijayanta, S.Pd.T, M.T.','19780824 200212 1 001','WAKIL DIREKTUR III',NULL,'images/pejabat/Setya Wijayanta.png',160,240,390,'top center','14px','Alamat kantor Kampus I Jl. Perintis Kemerdekaan No. 17 / Kampus II Jl. Abdul Syukur No. 17, Kota Tegal 52125 Telp. (0283) 351061. Menempuh pendidikan sarjana (S1) di bidang Pendidikan Teknik Universitas Negeri Yogyakarta, magister (S2) Teknik Sistem Transportasi, dan program Doktoral (S3) di bidang Ilmu Pendidikan. Pernah menjabat sebagai Ketua Program Studi Teknologi Otomotif / TRO PKTJ, Kepala Pusat Penelitian dan Pengabdian kepada Masyarakat (P3M) PKTJ, dan saat ini menjabat sebagai Wakil Direktur III (Bidang Ketarunaan, Alumni dan Kerja Sama) Politeknik Keselamatan Transportasi Jalan (PKTJ) Tegal. Beliau telah dianugerahi tanda kehormatan Satyalancana Karya Satya 20 Tahun dan Satyalancana Karya Satya 10 Tahun oleh Presiden Republik Indonesia.','[\"S3 - Doktor (Dr.) Ilmu Pendidikan / Manajemen Pendidikan\", \"S2 - Magister Teknik (M.T.) Sistem Transportasi\", \"S1 - Sarjana Pendidikan Teknik (S.Pd.T), Universitas Negeri Yogyakarta\"]','[\"Wakil Direktur III (Bidang Ketarunaan, Alumni dan Kerja Sama) PKTJ (2024 - Sekarang)\", \"Ketua Program Studi Teknologi Otomotif / TRO PKTJ\", \"Kepala Pusat Penelitian dan Pengabdian kepada Masyarakat (P3M) PKTJ\"]','[\"Satyalancana Karya Satya 20 Tahun Presiden RI\", \"Satyalancana Karya Satya 10 Tahun Presiden RI\"]',NULL,NULL,NULL,'2025/2026',4,1,'2026-08-31 20:12:26','2026-09-02 20:01:05'),(5,'Prima Anna Maria Gorety Cornelis, S.SiT.','19780415 200212 2 001','KEPALA BAGIAN ADMINISTRASI AKADEMIK DAN KETARUNAAN',NULL,'images/pejabat/Prima Anna.png',160,240,390,'top center','14px','Alamat kantor Kampus I Jl. Perintis Kemerdekaan No. 17 / Kampus II Jl. Abdul Syukur No. 17, Kota Tegal 52125 Telp. (0283) 351061. Menempuh pendidikan D4/S1 Terapan di bidang Sains Terapan Transportasi di Sekolah Tinggi Transportasi Darat (STTD) Bekasi. Pernah menjabat sebagai Pengelola Administrasi Ketarunaan dan Pengasuhan BPSDMP, Kepala Subbagian Administrasi Akademik PKTJ Tegal, dan saat ini menjabat sebagai Kepala Bagian Administrasi Akademik dan Ketarunaan (BAAK) Politeknik Keselamatan Transportasi Jalan (PKTJ) Tegal. Beliau telah dianugerahi tanda kehormatan Satyalancana Karya Satya 20 Tahun dan Satyalancana Karya Satya 10 Tahun oleh Presiden Republik Indonesia.','[\"D4 / S1 Terapan - Sarjana Sains Terapan Transportasi (S.SiT), STTD Bekasi\", \"Diklat Kepemimpinan Pengawas (PIM Tingkat IV)\", \"Bimbingan Teknis Pelayanan Prima Keterbukaan Informasi Publik\"]','[\"Kepala Bagian Administrasi Akademik dan Ketarunaan (BAAK) PKTJ (2024 - Sekarang)\", \"Kepala Subbagian Administrasi Akademik PKTJ\", \"Pengelola Administrasi Ketarunaan dan Pengasuhan BPSDMP\"]','[\"Satyalancana Karya Satya 20 Tahun Presiden RI\", \"Satyalancana Karya Satya 10 Tahun Presiden RI\"]',NULL,NULL,NULL,'2025/2026',5,1,'2026-08-31 20:12:26','2026-09-02 20:01:05'),(6,'Agus Hariyanto, S.Kom, M.Sc.','19790812 200502 1 001','Kepala Bagian Keuangan dan Administrasi Umum',NULL,'images/pejabat/Agus Hariyanto.png',160,240,390,'top center','14px','Alamat kantor Kampus I Jl. Perintis Kemerdekaan No. 17 / Kampus II Jl. Abdul Syukur No. 17, Kota Tegal 52125 Telp. (0283) 351061. Menempuh pendidikan Master of Science (M.Sc) di bidang Transport & Information Technology dan Sarjana Komputer (S.Kom) di Universitas Diponegoro. Memiliki sertifikasi dan kompetensi dalam Pengelolaan Keuangan BLU dan Pejabat Perbendaharaan Negara. Mengawali karir sebagai Ketua Program Studi Teknologi Rekayasa Otomotif (TRO) PKTJ, Kepala Unit Teknologi Informasi & Komunikasi (TIK) PKTJ, dan saat ini menjabat sebagai Kepala Bagian Keuangan dan Administrasi Umum Politeknik Keselamatan Transportasi Jalan (PKTJ) Tegal. Beliau telah dianugerahi tanda kehormatan Satyalancana Karya Satya 10 Tahun oleh Presiden Republik Indonesia serta Penghargaan Inovasi Sistem Pelayanan Informasi Digital.','[\"S2 - Master of Science (M.Sc) Transport & Information Technology\", \"S1 - Sarjana Komputer (S.Kom), Universitas Diponegoro\", \"Diklat Pengelolaan Keuangan BLU dan Pejabat Perbendaharaan Negara\"]','[\"Kepala Bagian Keuangan dan Administrasi Umum PKTJ (2024 - Sekarang)\", \"Kepala Unit Teknologi Informasi & Komunikasi (TIK) PKTJ\", \"Ketua Program Studi Teknologi Rekayasa Otomotif (TRO) PKTJ\"]','[\"Satyalancana Karya Satya 10 Tahun Presiden RI\", \"Penghargaan Inovasi Sistem Pelayanan Informasi Digital\"]',NULL,NULL,NULL,'2025/2026',6,1,'2026-08-31 20:12:26','2026-09-02 21:25:14');
