INSERT INTO `peraturans` VALUES (1,'Undang-Undang Nomor 14 Tahun 2008','UU No. 14 Tahun 2008',2008,'tentang Keterbukaan Informasi Publik (KIP)',NULL,'https://ppid.kemenhub.go.id/fileupload/informasi-berkala/20200728111256.uu14-2008_keterbukaan_informasi_publikascas.pdf',NULL,'Undang-Undang',1,1,'2026-08-27 00:55:55','2026-08-27 00:55:55'),(2,'Undang-Undang Nomor 25 Tahun 2009','UU No. 25 Tahun 2009',2009,'tentang Pelayanan Publik',NULL,'https://ppid.kemenhub.go.id/fileupload/informasi-berkala/20200728111618.UU_25_Tahun_2009dsd.pdf',NULL,'Undang-Undang',2,1,'2026-08-27 00:55:55','2026-08-27 00:55:55'),(3,'Undang-Undang Nomor 43 Tahun 2009','UU No. 43 Tahun 2009',2009,'tentang Kearsipan',NULL,'https://ppid.kemenhub.go.id/fileupload/informasi-berkala/20200728111804.UU_43_Tahun_2009cxzaaa.pdf',NULL,'Undang-Undang',3,1,'2026-08-27 00:55:55','2026-08-27 00:55:55'),(4,'Undang-Undang Nomor 40 Tahun 1999','UU No. 40 Tahun 1999',1999,'tentang Pers',NULL,'https://ppid.kemenhub.go.id/fileupload/informasi-berkala/20200728111403.UU_No._40_Tahun_1999_Tentang_Pers_sdcds.pdf',NULL,'Undang-Undang',4,1,'2026-08-27 00:55:55','2026-08-27 00:55:55'),(5,'Peraturan Komisi Informasi Pusat Nomor 1 Tahun 2021','Perki No. 1 Tahun 2021',2021,'tentang Standar Layanan Informasi Publik (SLIP)',NULL,'https://jdih.komisiinformasi.go.id/dokumen/view?id=3',NULL,'Komisi Informasi Pusat',5,1,'2026-08-27 00:55:55','2026-08-27 00:55:55'),(6,'Peraturan Komisi Informasi Pusat Nomor 1 Tahun 2013','Perki No. 1 Tahun 2013',2013,'tentang Prosedur Penyelesaian Sengketa Informasi Publik',NULL,'https://jdih.komisiinformasi.go.id/dokumen/view?id=32',NULL,'Komisi Informasi Pusat',6,1,'2026-08-27 00:55:55','2026-08-27 00:55:55'),(7,'Peraturan Menteri Perhubungan Nomor PM 46 Tahun 2018','PM 46 Tahun 2018',2018,'tentang Pedoman Pengelolaan Informasi dan Dokumentasi di Lingkungan Kementerian Perhubungan',NULL,'https://jdih.dephub.go.id/peraturan/detail?data=Gr3vFlNp4Kt7QFFckUxgA84ZI0WMg9fay4q9UjKV2wyZ8cQCY4NLOGj8MPnzt0Vmtu4jsBWzb0uHu4TwfZYTYVvd8W2gwcUFOmD4jpL4RJYs9W5LoU8994HTYDTO4pLhhdiMIQb9fXR66mY0ZhgiScyCWT',NULL,'Kementerian Perhubungan',7,1,'2026-08-27 00:55:55','2026-08-27 00:55:55'),(8,'Keputusan Menteri Perhubungan Nomor KM 117 Tahun 2022','KM 117 Tahun 2022',2022,'tentang Standar Operasional Prosedur (SOP) PPID di Lingkungan Kementerian Perhubungan',NULL,'https://jdih.dephub.go.id/peraturan/detail?data=DVtNwoS7MPwJH0L0fbMu888Qjvn9iOPTh8bMhTUoAkmH4ZGSMY8uwti4ZFAni36o6v4q9G43QwoOl4uSLnLEkb4P8W3k8dWBke54PXA0mVPAXKGke20ssIBJo225ZPgJyXPb0vjy5JCBIsLBGRejUHttlN',NULL,'Kementerian Perhubungan',8,1,'2026-08-27 00:55:55','2026-08-27 00:55:55'),(9,'Keputusan Sekretaris Jenderal Kemenhub Nomor KP-SKJ 15 Tahun 2025','KP-SKJ 15 Tahun 2025',2025,'tentang Penetapan Daftar Informasi Publik (DIP) Kementerian Perhubungan Tahun 2025',NULL,'https://ppid.kemenhub.go.id/fileupload/informasi-berkala/KP-SKJ-15-TAHUN-2025-DIP.pdf',NULL,'Kementerian Perhubungan',9,1,'2026-08-27 00:55:56','2026-08-27 00:55:56'),(10,'Keputusan Sekretaris Jenderal Kemenhub Nomor KP-SKJ 16 Tahun 2025','KP-SKJ 16 Tahun 2025',2025,'tentang Perubahan Kedua Atas Keputusan Sekjen KP 591 Tahun 2023 tentang Informasi yang Dikecualikan',NULL,'https://ppid.kemenhub.go.id/fileupload/informasi-berkala/KP-SKJ-16-TAHUN-2025-22072025142932.pdf',NULL,'Kementerian Perhubungan',10,1,'2026-08-27 00:55:56','2026-08-27 00:55:56'),(11,'Keputusan Sekretaris Jenderal Kemenhub Nomor KP-SKJ 25 Tahun 2024','KP-SKJ 25 Tahun 2024',2024,'tentang Daftar Informasi Publik (DIP) Kementerian Perhubungan Tahun 2024',NULL,'https://ppid.kemenhub.go.id/fileupload/informasi-berkala/20240610102903.DIP_Kemenhub_Tahun_2024.pdf',NULL,'Kementerian Perhubungan',11,1,'2026-08-27 00:55:56','2026-08-27 00:55:56'),(12,'Keputusan Sekretaris Jenderal Kemenhub Nomor KP-SKJ 24 Tahun 2024','KP-SKJ 24 Tahun 2024',2024,'tentang Perubahan Atas Keputusan Sekretaris Jenderal Nomor KP 591 Tahun 2023 tentang Informasi yang Dikecualikan',NULL,'https://ppid.kemenhub.go.id/fileupload/informasi-berkala/20240610103259.DIK_Kemenhub_Tahun_2024.pdf',NULL,'Kementerian Perhubungan',12,1,'2026-08-27 00:55:56','2026-08-27 00:55:56'),(13,'Keputusan Direktur PKTJ tentang Penetapan Pengelola PPID Pelaksana PKTJ Tegal','SK Direktur PKTJ 2025',2025,'tentang Struktur Organisasi dan Penunjukan Pejabat Pengelola Informasi dan Dokumentasi (PPID) Pelaksana Politeknik Keselamatan Transportasi Jalan Tegal',NULL,'https://pktj.ac.id/ppid',NULL,'PKTJ Tegal',13,1,'2026-08-27 00:55:56','2026-08-27 00:55:56'),(14,'Maklumat Pelayanan Informasi Publik PPID PKTJ Tegal','Maklumat PKTJ 2025/2026',2025,'Komitmen dan Janji Pelayanan Informasi Publik Politeknik Keselamatan Transportasi Jalan Sesuai Standar Layanan KIP',NULL,'https://pktj.ac.id/ppid',NULL,'PKTJ Tegal',14,1,'2026-08-27 00:55:56','2026-08-27 00:55:56'),(15,'SOP Tata Kelola dan Pelayanan Informasi Publik Politeknik Keselamatan Transportasi Jalan','SOP-PPID-PKTJ-01',2025,'Pedoman Teknis dan Alur Prosedur Pelayanan Permohonan Informasi, Pengajuan Keberatan, Pendokumentasian, dan Uji Konsekuensi Informasi di PKTJ',NULL,'https://pktj.ac.id/ppid',NULL,'PKTJ Tegal',15,1,'2026-08-27 00:55:56','2026-08-27 00:55:56');
