DROP TABLE IF EXISTS `permohonan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `permohonan` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned DEFAULT NULL,
  `nomor_registrasi` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `username` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nama_pemohon` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `jenis_identitas` enum('ktp','paspor','sim','lainnya') COLLATE utf8mb4_unicode_ci DEFAULT 'ktp',
  `email` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `password` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nomor_identitas` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `foto_ktp` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `alamat` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `perusahaan_instansi` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nomor_telepon` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `pekerjaan` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `npwp` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `jenis_informasi` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deskripsi_permohonan` longtext COLLATE utf8mb4_unicode_ci,
  `status_informasi_dikuasai` tinyint(1) NOT NULL DEFAULT '1',
  `status_informasi_belum_didokumentasikan` tinyint(1) NOT NULL DEFAULT '0',
  `bentuk_informasi_salinan` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `jenis_permohonan_salinan` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `format_informasi` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'digital',
  `berkas_pendukung` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'pending',
  `alasan_penolakan_text` text COLLATE utf8mb4_unicode_ci,
  `penolakan_pasal_uu` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tanggal_pemberitahuan_tertulis` date DEFAULT NULL,
  `tanggal_pemberian_informasi` date DEFAULT NULL,
  `biaya_salinan` decimal(15,2) DEFAULT NULL,
  `cara_pembayaran` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tanggal_permohonan` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `tanggal_selesai` timestamp NULL DEFAULT NULL,
  `kategori_laporan` enum('berkala','sertamerta','setiapsaat','dikecualikan') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `custom_fields_data` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `permohonan_username_unique` (`username`),
  KEY `permohonan_user_id_index` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
