INSERT INTO `profil_ppids` VALUES (2,'profil','Profil Singkat PPID Pelaksana PKTJ Tegal','Keterbukaan Informasi Publik Menuju Tata Kelola Pendidikan Vokasi yang Transparan dan Akuntabel',NULL,'<p>Pejabat Pengelola Informasi dan Dokumentasi (PPID) Pelaksana Politeknik Keselamatan Transportasi Jalan (PKTJ) dibentuk sebagai wujud komitmen keterbukaan informasi publik dan kepatuhan penuh terhadap <strong>Undang-Undang Nomor 14 Tahun 2008 tentang Keterbukaan Informasi Publik</strong> serta <strong>Peraturan Menteri Perhubungan Nomor PM 46 Tahun 2018 tentang Pedoman Pengelolaan Informasi dan Dokumentasi di Lingkungan Kementerian Perhubungan</strong>.</p>','Peran & Komitmen Pelayanan PPID PKTJ','<p>Sebagai Perguruan Tinggi Vokasi Kedinasan di bawah naungan Badan Pengembangan Sumber Daya Manusia Perhubungan (BPSDMP) Kementerian Perhubungan, PKTJ Tegal memiliki mandat luhur mencetak sumber daya manusia transportasi darat yang unggul, profesional, dan berintegritas.</p><p>PPID Pelaksana PKTJ hadir untuk memastikan hak publik atas informasi terpenuhi secara optimal, transparan, cepat, dan akuntabel melalui pemanfaatan teknologi digital terintegrasi serta penyediaan fasilitas meja layanan yang inklusif dan ramah disabilitas.</p>','Pusat Layanan Keterbukaan Informasi Publik dan Dokumentasi Resmi Politeknik Keselamatan Transportasi Jalan (PKTJ) Tegal.',0,NULL,NULL,'[]','2026-03-09 03:45:23','2026-08-31 19:23:23'),(3,'layanan-daftar',NULL,'Daftar Informasi Publik',NULL,'<div class=\"content-box\">\n            <h2 class=\"section-title\">Pengertian Daftar Informasi Publik</h2>\n            <div class=\"profil-content\">\n                <p><strong>Daftar Informasi Publik</strong> adalah katalog yang berisi kumpulan informasi yang tersedia dan dapat diakses oleh publik. Daftar ini disusun secara sistematis dan diklasifikasikan berdasarkan jenis, kategori, dan subyek informasi.</p>\n\n                <p>Daftar informasi publik wajib disusun oleh setiap badan publik sesuai dengan Peraturan Pemerintah Nomor 61 Tahun 2010 dan harus diperbaharui secara berkala.</p>\n            </div>\n        </div>\n\n        <div class=\"filter-buttons text-center\">\n            <button class=\"btn btn-outline-primary active\" onclick=\"filterInfo(\'all\')\">Semua</button>\n            <button class=\"btn btn-outline-success\" onclick=\"filterInfo(\'berkala\')\">Berkala</button>\n            <button class=\"btn btn-outline-info\" onclick=\"filterInfo(\'serta-merta\')\">Serta Merta</button>\n            <button class=\"btn btn-outline-warning\" onclick=\"filterInfo(\'setiap-saat\')\">Setiap Saat</button>\n        </div>\n\n        <!-- Informasi Berkala -->\n        <div class=\"info-category\">\n            <i class=\"fas fa-calendar-alt\"></i>\n            <h4>Informasi Berkala</h4>\n            <p>Informasi yang wajib disediakan dan diumumkan secara rutin</p>\n        </div>\n\n        <div class=\"content-box\">\n            <h3 class=\"text-primary mb-4\"><i class=\"fas fa-building me-2\"></i>Profil Badan Publik</h3>\n            <ul class=\"info-list\" data-category=\"berkala\">\n                <li>\n                    <strong>Visi dan Misi PPID PKTJ</strong>\n                    <small>Dokumen visi dan misi Pejabat Pengelola Informasi dan Dokumentasi</small>\n                    <br><button class=\"btn btn-download btn-sm\">Download</button>\n                </li>\n                <li>\n                    <strong>Tugas Pokok dan Fungsi PPID</strong>\n                    <small>Deskripsi tugas dan fungsi PPID berdasarkan peraturan perundang-undangan</small>\n                    <br><button class=\"btn btn-download btn-sm\">Download</button>\n                </li>\n                <li>\n                    <strong>Struktur Organisasi PPID</strong>\n                    <small>Diagram dan penjelasan struktur organisasi PPID PKTJ</small>\n                    <br><button class=\"btn btn-download btn-sm\">Download</button>\n                </li>\n                <li>\n                    <strong>Profil Pejabat PPID</strong>\n                    <small>Data pejabat yang menangani pengelolaan informasi dan dokumentasi</small>\n                    <br><button class=\"btn btn-download btn-sm\">Download</button>\n                </li>\n                <li>\n                    <strong>Program Kerja PPID</strong>\n                    <small>Rencana program kerja PPID untuk tahun berjalan</small>\n                    <br><button class=\"btn btn-download btn-sm\">Download</button>\n                </li>\n            </ul>\n\n            <h3 class=\"text-primary mb-4 mt-5\"><i class=\"fas fa-chart-line me-2\"></i>Laporan Kegiatan</h3>\n            <ul class=\"info-list\" data-category=\"berkala\">\n                <li>\n                    <strong>Laporan Tahunan PPID 2025</strong>\n                    <small>Laporan kegiatan PPID selama tahun 2025</small>\n                    <br><button class=\"btn btn-download btn-sm\">Download</button>\n                </li>\n                <li>\n                    <strong>Laporan Triwulanan PPID</strong>\n                    <small>Laporan kegiatan PPID per triwulan</small>\n                    <br><button class=\"btn btn-download btn-sm\">Download</button>\n                </li>\n                <li>\n                    <strong>Laporan Kinerja PPID</strong>\n                    <small>Evaluasi kinerja PPID dalam melayani informasi publik</small>\n                    <br><button class=\"btn btn-download btn-sm\">Download</button>\n                </li>\n                <li>\n                    <strong>Statistik Permintaan Informasi</strong>\n                    <small>Data statistik permintaan informasi publik</small>\n                    <br><button class=\"btn btn-download btn-sm\">Download</button>\n                </li>\n            </ul>\n\n            <h3 class=\"text-primary mb-4 mt-5\"><i class=\"fas fa-file-invoice-dollar me-2\"></i>Laporan Keuangan</h3>\n            <ul class=\"info-list\" data-category=\"berkala\">\n                <li>\n                    <strong>Laporan Keuangan Tahunan</strong>\n                    <small>Laporan keuangan PPID tahun 2025</small>\n                    <br><button class=\"btn btn-download btn-sm\">Download</button>\n                </li>\n                <li>\n                    <strong>Anggaran PPID</strong>\n                    <small>Rencana anggaran PPID untuk tahun berjalan</small>\n                    <br><button class=\"btn btn-download btn-sm\">Download</button>\n                </li>\n            </ul>\n        </div>\n\n        <!-- Informasi Setiap Saat -->\n        <div class=\"info-category\">\n            <i class=\"fas fa-clock\"></i>\n            <h4>Informasi Setiap Saat</h4>\n            <p>Informasi yang dapat diakses setiap saat melalui berbagai kanal</p>\n        </div>\n\n        <div class=\"content-box\">\n            <h3 class=\"text-primary mb-4\"><i class=\"fas fa-cogs me-2\"></i>Pelayanan Informasi</h3>\n            <ul class=\"info-list\" data-category=\"setiap-saat\">\n                <li>\n                    <strong>Maklumat Pelayanan PPID</strong>\n                    <small>Informasi tentang prosedur, waktu, dan biaya pelayanan</small>\n                    <br><button class=\"btn btn-download btn-sm\">Download</button>\n                </li>\n                <li>\n                    <strong>Standar Operasional Prosedur</strong>\n                    <small>SOP pengelolaan informasi dan dokumentasi</small>\n                    <br><button class=\"btn btn-download btn-sm\">Download</button>\n                </li>\n                <li>\n                    <strong>Formulir Permohonan Informasi</strong>\n                    <small>Format formulir untuk mengajukan permintaan informasi</small>\n                    <br><button class=\"btn btn-download btn-sm\">Download</button>\n                </li>\n                <li>\n                    <strong>Formulir Keberatan</strong>\n                    <small>Format formulir untuk mengajukan keberatan atas keputusan PPID</small>\n                    <br><button class=\"btn btn-download btn-sm\">Download</button>\n                </li>\n            </ul>\n\n            <h3 class=\"text-primary mb-4 mt-5\"><i class=\"fas fa-gavel me-2\"></i>Regulasi</h3>\n            <ul class=\"info-list\" data-category=\"setiap-saat\">\n                <li>\n                    <strong>Undang-Undang Keterbukaan Informasi Publik</strong>\n                    <small>UU Nomor 14 Tahun 2008</small>\n                    <br><button class=\"btn btn-download btn-sm\">Download</button>\n                </li>\n                <li>\n                    <strong>Peraturan Pemerintah Nomor 61 Tahun 2010</strong>\n                    <small>PP tentang Pelaksanaan UU KIP</small>\n                    <br><button class=\"btn btn-download btn-sm\">Download</button>\n                </li>\n                <li>\n                    <strong>Peraturan Komisi Informasi</strong>\n                    <small>Regulasi yang diterbitkan oleh Komisi Informasi Pusat</small>\n                    <br><button class=\"btn btn-download btn-sm\">Download</button>\n                </li>\n            </ul>\n\n            <h3 class=\"text-primary mb-4 mt-5\"><i class=\"fas fa-users me-2\"></i>Informasi Umum</h3>\n            <ul class=\"info-list\" data-category=\"setiap-saat\">\n                <li>\n                    <strong>Profil PPID PKTJ</strong>\n                    <small>Informasi lengkap tentang PPID PKTJ</small>\n                    <br><button class=\"btn btn-download btn-sm\">Download</button>\n                </li>\n                <li>\n                    <strong>Daftar Informasi Publik</strong>\n                    <small>Katalog lengkap informasi yang tersedia</small>\n                    <br><button class=\"btn btn-download btn-sm\">Download</button>\n                </li>\n                <li>\n                    <strong>Kontak PPID</strong>\n                    <small>Informasi kontak dan alamat PPID</small>\n                    <br><button class=\"btn btn-download btn-sm\">Download</button>\n                </li>\n                <li>\n                    <strong>FAQ PPID</strong>\n                    <small>Pertanyaan yang sering diajukan</small>\n                    <br><button class=\"btn btn-download btn-sm\">Download</button>\n                </li>\n            </ul>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Cara Mengakses Informasi</h2>\n            <div class=\"row\">\n                <div class=\"col-md-6\">\n                    <h5><i class=\"fas fa-globe text-primary me-2\"></i>Online</h5>\n                    <ul>\n                        <li>Melalui website PPID PKTJ</li>\n                        <li>Download dokumen langsung</li>\n                        <li>Pencarian informasi real-time</li>\n                        <li>Akses 24 jam</li>\n                    </ul>\n                </div>\n                <div class=\"col-md-6\">\n                    <h5><i class=\"fas fa-building text-success me-2\"></i>Offline</h5>\n                    <ul>\n                        <li>Datang langsung ke kantor PPID</li>\n                        <li>Mengajukan permintaan informasi</li>\n                        <li>Mendapatkan dokumen fisik</li>\n                        <li>Konsultasi langsung dengan petugas</li>\n                    </ul>\n                </div>\n            </div>\n\n            <div class=\"alert alert-info mt-4\">\n                <h6><i class=\"fas fa-info-circle me-2\"></i>Pemberitahuan</h6>\n                <p>Daftar informasi publik ini diperbaharui secara berkala. Untuk mendapatkan informasi terkini, silakan hubungi PPID atau akses website secara berkala.</p>\n            </div>\n        </div>\n<div class=\"premium-box-outer\" style=\"display: inline-block; width: 85%; max-width: 100%; height: 500px; margin: 20px 0; text-align: left; vertical-align: top;\">\n  <div class=\"premium-box-wrapper\" style=\"width: 100%; height: 100%; overflow: hidden; border-radius: 24px; border: 1px solid #e2e8f0; box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1); background: #ffffff;\">\n    <iframe src=\"/preview-dokumen?file=https%3A%2F%2Fdrive.google.com%2Ffile%2Fd%2F1bxbh53yoMpJbS7_pb0PeqDNmbzc3LeRi%2Fview&title=Dokumen+Informasi+Publik&is_blurred=1\" style=\"width: 100%; height: 100%; border: none;\"></iframe>\n  </div>\n</div>',NULL,NULL,NULL,1,NULL,NULL,'[]','2026-03-25 20:08:13','2026-03-26 00:05:26'),(4,'maklumat-pelayanan','Maklumat Pelayanan','Maklumat Pelayanan',NULL,'<div class=\"content-box\">\n            <h2 class=\"section-title\">Pengertian Maklumat Pelayanan</h2>\n            <div class=\"profil-content\">\n                <p><strong>Maklumat Pelayanan</strong> adalah informasi yang wajib disediakan oleh badan publik untuk memberikan informasi tentang pelayanan yang diberikan kepada masyarakat. Maklumat pelayanan memuat standar, prosedur, dan biaya pelayanan informasi publik.</p>\n\n                <p>Maklumat pelayanan disusun berdasarkan Peraturan Komisi Informasi Nomor 1 Tahun 2021 tentang Standar Layanan Informasi Publik dan harus memuat informasi yang jelas, lengkap, dan mudah dipahami oleh masyarakat.</p>\n            </div>\n        </div>\n\n        <div class=\"row\">\n            <div class=\"col-lg-6\">\n                <div class=\"service-card text-center\">\n                    <i class=\"fas fa-clock\"></i>\n                    <h5>Waktu Pelayanan</h5>\n                    <p>Informasi tentang jam kerja, hari kerja, dan waktu pelayanan informasi publik</p>\n                    <ul class=\"list-unstyled\">\n                        <li><strong>Hari:</strong> Senin - Jumat</li>\n                        <li><strong>Jam:</strong> 08:00 - 16:00 WIB</li>\n                        <li><strong>Istirahat:</strong> 12:00 - 13:00 WIB</li>\n                    </ul>\n                </div>\n            </div>\n\n            <div class=\"col-lg-6\">\n                <div class=\"service-card text-center\">\n                    <i class=\"fas fa-route\"></i>\n                    <h5>Prosedur Pelayanan</h5>\n                    <p>Langkah-langkah yang harus dilakukan pemohon informasi untuk mendapatkan pelayanan</p>\n                    <ul class=\"list-unstyled\">\n                        <li><strong>1.</strong> Mengajukan permintaan</li>\n                        <li><strong>2.</strong> Verifikasi identitas</li>\n                        <li><strong>3.</strong> Proses permintaan</li>\n                        <li><strong>4.</strong> Penyerahan informasi</li>\n                    </ul>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"row\">\n            <div class=\"col-lg-6\">\n                <div class=\"service-card text-center\">\n                    <i class=\"fas fa-money-bill-wave\"></i>\n                    <h5>Biaya Pelayanan</h5>\n                    <p>Informasi tentang biaya yang dikenakan untuk pelayanan informasi publik</p>\n                    <ul class=\"list-unstyled\">\n                        <li><strong>Informasi Umum:</strong> Gratis</li>\n                        <li><strong>Penggandaan:</strong> Rp 500/lembar</li>\n                        <li><strong>Pengiriman:</strong> Sesuai ongkos kirim</li>\n                    </ul>\n                </div>\n            </div>\n\n            <div class=\"col-lg-6\">\n                <div class=\"service-card text-center\">\n                    <i class=\"fas fa-headset\"></i>\n                    <h5>Kontak Pelayanan</h5>\n                    <p>Informasi kontak yang dapat dihubungi untuk mendapatkan pelayanan informasi</p>\n                    <ul class=\"list-unstyled\">\n                        <li><strong>Telepon:</strong> (021) 3847790</li>\n                        <li><strong>Email:</strong> ppid@pktj.dephub.go.id</li>\n                        <li><strong>Website:</strong> ppid.pktj.ac.id</li>\n                    </ul>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Alur Pelayanan Informasi Publik</h2>\n            <div class=\"timeline\">\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">1. Penerimaan Permintaan</h6>\n                        <p>PPID menerima permintaan informasi melalui berbagai kanal (online, datang langsung, surat, telepon)</p>\n                    </div>\n                </div>\n\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">2. Pendaftaran & Verifikasi</h6>\n                        <p>Permintaan didaftarkan dan diverifikasi kelengkapan data pemohon informasi</p>\n                    </div>\n                </div>\n\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">3. Klarifikasi & Konfirmasi</h6>\n                        <p>PPID melakukan klarifikasi jika diperlukan dan mengkonfirmasi pemahaman permintaan</p>\n                    </div>\n                </div>\n\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">4. Pencarian & Pengolahan Informasi</h6>\n                        <p>PPID mencari dan mengolah informasi yang diminta sesuai dengan prosedur yang berlaku</p>\n                    </div>\n                </div>\n\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">5. Pemberitahuan & Penyerahan</h6>\n                        <p>PPID memberitahukan ketersediaan informasi dan menyerahkan informasi kepada pemohon</p>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Standar Biaya Pelayanan</h2>\n            <div class=\"price-table\">\n                <table>\n                    <thead>\n                        <tr>\n                            <th>Jenis Pelayanan</th>\n                            <th>Biaya</th>\n                            <th>Keterangan</th>\n                        </tr>\n                    </thead>\n                    <tbody>\n                        <tr>\n                            <td>Pemberian Informasi Umum</td>\n                            <td>Gratis</td>\n                            <td>Informasi yang dapat langsung diberikan</td>\n                        </tr>\n                        <tr>\n                            <td>Penggandaan Dokumen</td>\n                            <td>Rp 500/lembar</td>\n                            <td>Untuk dokumen A4 berwarna</td>\n                        </tr>\n                        <tr>\n                            <td>Scan Dokumen</td>\n                            <td>Rp 1.000/lembar</td>\n                            <td>Dalam format PDF</td>\n                        </tr>\n                        <tr>\n                            <td>Pengiriman Dokumen</td>\n                            <td>Sesuai ongkos kirim</td>\n                            <td>Melalui pos/jasa kurir</td>\n                        </tr>\n                        <tr>\n                            <td>Media Penyimpanan</td>\n                            <td>Rp 10.000/CD</td>\n                            <td>CD/DVD kosong</td>\n                        </tr>\n                        <tr>\n                            <td>Biaya Administrasi</td>\n                            <td>Rp 5.000</td>\n                            <td>Untuk setiap permintaan</td>\n                        </tr>\n                    </tbody>\n                </table>\n            </div>\n            <div class=\"alert alert-info mt-3\">\n                <h6><i class=\"fas fa-info-circle me-2\"></i>Catatan:</h6>\n                <p>Biaya di atas dapat berubah sesuai dengan ketentuan yang berlaku. Untuk informasi terkini, silakan hubungi PPID.</p>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Persyaratan Pengajuan Informasi</h2>\n            <div class=\"profil-content\">\n                <h5 class=\"text-primary mb-3\">Persyaratan Administratif:</h5>\n                <ul>\n                    <li>Formulir permohonan informasi yang telah diisi lengkap</li>\n                    <li>Fotokopi identitas diri (KTP/SIM/Paspor)</li>\n                    <li>Surat kuasa (jika diwakilkan)</li>\n                    <li>Surat keterangan dari instansi (untuk keperluan penelitian)</li>\n                </ul>\n\n                <h5 class=\"text-primary mb-3 mt-4\">Persyaratan Teknis:</h5>\n                <ul>\n                    <li>Permintaan informasi harus jelas dan spesifik</li>\n                    <li>Mencantumkan tujuan penggunaan informasi</li>\n                    <li>Menyertakan alamat email/telepon untuk konfirmasi</li>\n                    <li>Menyatakan kesanggupan membayar biaya (jika ada)</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"row\">\n            <div class=\"col-lg-8\">\n                <div class=\"content-box\">\n                    <h2 class=\"section-title\">Jaminan Pelayanan</h2>\n                    <div class=\"profil-content\">\n                        <p>PPID PKTJ menjamin pelayanan informasi publik yang:</p>\n                        <div class=\"row mt-3\">\n                            <div class=\"col-md-6\">\n                                <h6><i class=\"fas fa-check-circle text-success me-2\"></i>Kualitas</h6>\n                                <p>Informasi yang akurat, benar, dan tidak menyesatkan</p>\n                            </div>\n                            <div class=\"col-md-6\">\n                                <h6><i class=\"fas fa-clock text-info me-2\"></i>Kesepatan Waktu</h6>\n                                <p>Pelayanan sesuai dengan waktu yang telah ditentukan</p>\n                            </div>\n                            <div class=\"col-md-6\">\n                                <h6><i class=\"fas fa-balance-scale text-warning me-2\"></i>Keadilan</h6>\n                                <p>Pelayanan yang sama dan setara untuk semua pihak</p>\n                            </div>\n                            <div class=\"col-md-6\">\n                                <h6><i class=\"fas fa-shield-alt text-danger me-2\"></i>Keamanan</h6>\n                                <p>Perlindungan data pribadi dan kerahasiaan informasi</p>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"col-lg-4\">\n                <div class=\"contact-box\">\n                    <i class=\"fas fa-comments\"></i>\n                    <h4>Punya Pertanyaan?</h4>\n                    <p>Hubungi kami untuk mendapatkan informasi lebih lanjut tentang pelayanan PPID PKTJ</p>\n                    <div class=\"mt-3\">\n                        <p><strong>📞 (021) 3847790</strong></p>\n                        <p><strong>✉️ ppid@pktj.dephub.go.id</strong></p>\n                        <a href=\"/permohonan-informasi\" class=\"btn btn-light mt-3\">\n                            <i class=\"fas fa-file-alt me-2\"></i>Ajukan Permintaan\n                        </a>\n                    </div>\n                </div>\n            </div>\n        </div>\n<div class=\"premium-box-outer\" style=\"display: inline-block; width: 85%; max-width: 100%; height: 500px; margin: 20px 0; text-align: left; vertical-align: top;\">\n  <div clas