>\n                            <td>423</td>\n                            <td>4.8</td>\n                            <td><span class=\"badge bg-success\">96.2%</span></td>\n                            <td>89.4%</td>\n                        </tr>\n                        <tr>\n                            <td><i class=\"fas fa-chalkboard-teacher text-success me-2\"></i>Dosen/Peneliti</td>\n                            <td>345</td>\n                            <td>4.7</td>\n                            <td><span class=\"badge bg-success\">94.8%</span></td>\n                            <td>87.2%</td>\n                        </tr>\n                        <tr>\n                            <td><i class=\"fas fa-users text-warning me-2\"></i>Masyarakat Umum</td>\n                            <td>289</td>\n                            <td>4.6</td>\n                            <td><span class=\"badge bg-success\">92.7%</span></td>\n                            <td>85.1%</td>\n                        </tr>\n                        <tr>\n                            <td><i class=\"fas fa-newspaper text-info me-2\"></i>Media/Jurnalis</td>\n                            <td>156</td>\n                            <td>4.5</td>\n                            <td><span class=\"badge bg-success\">90.4%</span></td>\n                            <td>82.7%</td>\n                        </tr>\n                        <tr>\n                            <td><i class=\"fas fa-building text-danger me-2\"></i>Instansi Pemerintah</td>\n                            <td>34</td>\n                            <td>4.2</td>\n                            <td><span class=\"badge bg-warning\">85.3%</span></td>\n                            <td>76.5%</td>\n                        </tr>\n                    </tbody>\n                </table>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Saran dan Masukan Pemohon</h2>\n            <div class=\"profil-content\">\n                <p>Berdasarkan hasil survey, berikut adalah saran dan masukan dari pemohon informasi yang perlu menjadi perhatian PPID:</p>\n\n                <div class=\"row mt-4\">\n                    <div class=\"col-md-6\">\n                        <h5><i class=\"fas fa-thumbs-up text-success me-2\"></i>Hal Positif yang Dihargai</h5>\n                        <ul>\n                            <li>Responsivitas petugas dalam memberikan pelayanan</li>\n                            <li>Kemudahan akses informasi melalui website</li>\n                            <li>Kompetensi petugas dalam menjelaskan informasi</li>\n                            <li>Kerapian dan kejelasan dokumen yang diberikan</li>\n                            <li>Fasilitas yang memadai untuk pelayanan langsung</li>\n                        </ul>\n                    </div>\n                    <div class=\"col-md-6\">\n                        <h5><i class=\"fas fa-lightbulb text-warning me-2\"></i>Saran Perbaikan</h5>\n                        <ul>\n                            <li>Perluasan jam layanan untuk hari Sabtu</li>\n                            <li>Penambahan kanal komunikasi WhatsApp</li>\n                            <li>Peningkatan kecepatan respon email</li>\n                            <li>Penambahan informasi dalam berbagai bahasa</li>\n                            <li>Pengembangan aplikasi mobile</li>\n                        </ul>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Tren Kepuasan Tahunan</h2>\n\n            <div class=\"survey-card\">\n                <i class=\"fas fa-chart-line\"></i>\n                <h5>Perkembangan Indeks Kepuasan 2020-2024</h5>\n                <div class=\"chart-container\">\n                    <img src=\"https://via.placeholder.com/600x300/d4af37/white?text=Chart+Tren+Tahunan\" alt=\"Chart Tren\" class=\"img-fluid\">\n                    <p class=\"text-muted mt-2\">Grafik tren kepuasan layanan informasi publik 2020-2024</p>\n                </div>\n            </div>\n\n            <div class=\"stats-grid\">\n                <div class=\"rating-card\">\n                    <div class=\"rating-score\">2020</div>\n                    <div class=\"rating-label\">3.8</div>\n                    <small class=\"text-muted\">Baseline</small>\n                </div>\n                <div class=\"rating-card\">\n                    <div class=\"rating-score\">2021</div>\n                    <div class=\"rating-label\">4.1</div>\n                    <small class=\"text-muted\">+8.2%</small>\n                </div>\n                <div class=\"rating-card\">\n                    <div class=\"rating-score\">2022</div>\n                    <div class=\"rating-label\">4.3</div>\n                    <small class=\"text-muted\">+4.9%</small>\n                </div>\n                <div class=\"rating-card\">\n                    <div class=\"rating-score\">2023</div>\n                    <div class=\"rating-label\">4.5</div>\n                    <small class=\"text-muted\">+4.7%</small>\n                </div>\n                <div class=\"rating-card\">\n                    <div class=\"rating-score\">2024</div>\n                    <div class=\"rating-label\">4.7</div>\n                    <small class=\"text-muted\">+4.4%</small>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"improvement-list\">\n            <h6><i class=\"fas fa-target me-2\"></i>Inisiatif Perbaikan Layanan 2025</h6>\n            <ul>\n                <li>Meningkatkan kecepatan respon melalui implementasi sistem manajemen antrian online</li>\n                <li>Mengembangkan aplikasi mobile untuk kemudahan akses informasi</li>\n                <li>Memperluas jam operasional layanan informasi</li>\n                <li>Meningkatkan kompetensi petugas melalui pelatihan berkala</li>\n                <li>Mengembangkan sistem feedback real-time untuk perbaikan berkelanjutan</li>\n                <li>Memperluas kanal komunikasi digital (WhatsApp, chat online)</li>\n                <li>Meningkatkan kualitas dan kuantitas informasi yang disediakan</li>\n                <li>Mengembangkan sistem monitoring dan evaluasi layanan</li>\n            </ul>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Download Laporan Lengkap</h2>\n            <div class=\"profil-content\">\n                <p>Untuk mendapatkan laporan lengkap hasil survey kepuasan layanan informasi publik PPID PKTJ, silakan download dokumen berikut:</p>\n\n                <div class=\"row mt-4\">\n                    <div class=\"col-md-6\">\n                        <div class=\"d-flex align-items-center p-3 border rounded\">\n                            <i class=\"fas fa-file-pdf text-danger me-3\" style=\"font-size: 24px;\"></i>\n                            <div class=\"flex-grow-1\">\n                                <h6 class=\"mb-1\">Laporan Survey 2024</h6>\n                                <small class=\"text-muted\">PDF • 4.1 MB • 124 halaman</small>\n                            </div>\n                            <button class=\"download-btn\">\n                                <i class=\"fas fa-download me-1\"></i>Download\n                            </button>\n                        </div>\n                    </div>\n                    <div class=\"col-md-6\">\n                        <div class=\"d-flex align-items-center p-3 border rounded\">\n                            <i class=\"fas fa-file-excel text-success me-3\" style=\"font-size: 24px;\"></i>\n                            <div class=\"flex-grow-1\">\n                                <h6 class=\"mb-1\">Data Survey 2024</h6>\n                                <small class=\"text-muted\">Excel • 2.8 MB • Dataset lengkap</small>\n                            </div>\n                            <button class=\"download-btn\">\n                                <i class=\"fas fa-download me-1\"></i>Download\n                            </button>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n<div class=\"premium-box-outer\" style=\"display: inline-block; width: 85%; max-width: 100%; height: 500px; margin: 20px 0; text-align: left; vertical-align: top;\">\n  <div class=\"premium-box-wrapper\" style=\"width: 100%; height: 100%; overflow: hidden; border-radius: 24px; border: 1px solid #e2e8f0; box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1); background: #ffffff;\">\n    <iframe src=\"/preview-dokumen?file=https%3A%2F%2Fdrive.google.com%2Ffile%2Fd%2F1bxbh53yoMpJbS7_pb0PeqDNmbzc3LeRi%2Fview&title=Dokumen+Informasi+Publik&is_blurred=1\" style=\"width: 100%; height: 100%; border: none;\"></iframe>\n  </div>\n</div>',NULL,'',NULL,1,NULL,NULL,'[]','2026-03-25 20:08:13','2026-03-26 00:05:26'),(8,'sop-permintaan','Sop permintaan','SOP Permintaan Informasi',NULL,'<div class=\"content-box\">\n            <h2 class=\"section-title\">Dasar Hukum</h2>\n            <div class=\"profil-content\">\n                <p>Standar Operasional Prosedur (SOP) Permintaan Informasi Publik PPID PKTJ disusun berdasarkan:</p>\n                <ul>\n                    <li>Undang-Undang Nomor 14 Tahun 2008 tentang Keterbukaan Informasi Publik</li>\n                    <li>Peraturan Pemerintah Nomor 61 Tahun 2010 tentang Pelaksanaan Undang-Undang Nomor 14 Tahun 2008 tentang Keterbukaan Informasi Publik</li>\n                    <li>Peraturan Komisi Informasi Nomor 1 Tahun 2021 tentang Standar Layanan Informasi Publik</li>\n                    <li>Keputusan Direktur Jenderal Perhubungan Udara Nomor KP 345 Tahun 2018 tentang SOP PPID PKTJ</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Persyaratan Pengajuan</h2>\n            <div class=\"requirements-box\">\n                <h6><i class=\"fas fa-clipboard-list me-2\"></i>Persyaratan Administratif:</h6>\n                <ul>\n                    <li>Formulir permohonan informasi yang telah diisi lengkap</li>\n                    <li>Fotokopi identitas diri (KTP/SIM/Paspor) pemohon</li>\n                    <li>Surat kuasa (jika diwakilkan oleh pihak lain)</li>\n                    <li>Surat keterangan dari instansi (untuk keperluan penelitian)</li>\n                </ul>\n\n                <h6 class=\"mt-4\"><i class=\"fas fa-file-signature me-2\"></i>Persyaratan Teknis:</h6>\n                <ul>\n                    <li>Permintaan informasi harus jelas dan spesifik</li>\n                    <li>Mencantumkan tujuan penggunaan informasi</li>\n                    <li>Menyertakan alamat email/telepon untuk konfirmasi</li>\n                    <li>Menyatakan kesanggupan membayar biaya (jika ada)</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Alur Prosedur Permintaan Informasi</h2>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">1</div>\n                <i class=\"fas fa-file-alt\"></i>\n                <h5>Penerimaan Permintaan</h5>\n                <p>PPID menerima permintaan informasi melalui berbagai kanal: online, datang langsung, surat, atau telepon. Permintaan dicatat dalam register khusus.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">2</div>\n                <i class=\"fas fa-user-check\"></i>\n                <h5>Verifikasi dan Klarifikasi</h5>\n                <p>PPID melakukan verifikasi kelengkapan data pemohon dan melakukan klarifikasi jika permintaan informasi kurang jelas atau perlu penjelasan lebih lanjut.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">3</div>\n                <i class=\"fas fa-search\"></i>\n                <h5>Pencarian dan Pengolahan Informasi</h5>\n                <p>PPID mencari informasi yang diminta dari database atau unit kerja terkait. Informasi diproses sesuai dengan ketentuan klasifikasi informasi publik.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">4</div>\n                <i class=\"fas fa-gavel\"></i>\n                <h5>Pengujian Konsekuensi</h5>\n                <p>Jika informasi yang diminta termasuk informasi yang dikecualikan, PPID melakukan pengujian konsekuensi untuk menentukan dapat atau tidaknya informasi diberikan.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">5</div>\n                <i class=\"fas fa-clock\"></i>\n                <h5>Penetapan Jangka Waktu</h5>\n                <p>PPID menetapkan jangka waktu penyelesaian sesuai dengan jenis informasi: maksimal 10 hari kerja untuk informasi tersedia, maksimal 30 hari kerja untuk informasi perlu penyiapan.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">6</div>\n                <i class=\"fas fa-envelope\"></i>\n                <h5>Pemberitahuan Keputusan</h5>\n                <p>PPID memberitahukan kepada pemohon tentang ketersediaan informasi atau alasan penolakan. Pemberitahuan dilakukan secara tertulis dalam jangka waktu maksimal 10 hari kerja.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">7</div>\n                <i class=\"fas fa-hand-holding\"></i>\n                <h5>Penyerahan Informasi</h5>\n                <p>Informasi diserahkan kepada pemohon melalui berbagai cara: email, datang langsung ke kantor PPID, atau pengiriman melalui pos/jasa kurir.</p>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Jangka Waktu Penyelesaian</h2>\n            <div class=\"timeline\">\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">Informasi Tersedia Langsung</h6>\n                        <p>Informasi yang sudah tersedia dalam bentuk siap saji dan dapat langsung diberikan kepada pemohon.</p>\n                        <div class=\"alert alert-success mt-2\">\n                            <strong>Waktu Penyelesaian:</strong> Maksimal 10 hari kerja sejak permintaan diterima secara lengkap\n                        </div>\n                    </div>\n                </div>\n\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-warning\">Informasi Perlu Penyiapan</h6>\n                        <p>Informasi yang perlu dicari, dikumpulkan, atau diproses terlebih dahulu sebelum dapat diberikan.</p>\n                        <div class=\"alert alert-warning mt-2\">\n                            <strong>Waktu Penyelesaian:</strong> Maksimal 30 hari kerja sejak permintaan diterima secara lengkap\n                        </div>\n                    </div>\n                </div>\n\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-info\">Perpanjangan Jangka Waktu</h6>\n                        <p>Dalam hal tertentu, jangka waktu dapat diperpanjang dengan pemberitahuan tertulis kepada pemohon.</p>\n                        <div class=\"alert alert-info mt-2\">\n                            <strong>Perpanjangan:</strong> Maksimal 30 hari kerja dengan alasan yang sah\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Biaya Pelayanan</h2>\n            <div class=\"profil-content\">\n                <p>Biaya pelayanan informasi publik PPID PKTJ ditetapkan berdasarkan Standar Biaya Pelayanan Informasi Publik yang berlaku:</p>\n\n                <div class=\"row mt-4\">\n                    <div class=\"col-md-6\">\n                        <h5><i class=\"fas fa-money-bill-wave text-success me-2\"></i>Biaya Gratis</h5>\n                        <ul>\n                            <li>Pemberian informasi umum</li>\n                            <li>Informasi yang berkaitan kepentingan umum</li>\n                            <li>Pemberitahuan tertulis keputusan PPID</li>\n                            <li>Konsultasi awal permintaan informasi</li>\n                        </ul>\n                    </div>\n                    <div class=\"col-md-6\">\n                        <h5><i class=\"fas fa-calculator text-warning me-2\"></i>Biaya Berbayar</h5>\n                        <ul>\n                            <li>Penggandaan dokumen: Rp 500/lembar</li>\n                            <li>Scan dokumen: Rp 1.000/lembar</li>\n                            <li>Media penyimpanan: Rp 10.000/CD</li>\n                            <li>Pengiriman dokumen: sesuai ongkos kirim</li>\n                        </ul>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Hak dan Kewajiban</h2>\n            <div class=\"row\">\n                <div class=\"col-lg-6\">\n                    <h5 class=\"text-primary\"><i class=\"fas fa-user-check me-2\"></i>Hak Pemohon Informasi</h5>\n                    <ul class=\"mt-3\">\n                        <li>Memperoleh informasi yang diminta</li>\n                        <li>Mendapatkan pelayanan yang baik dan profesional</li>\n                        <li>Mengajukan keberatan atas keputusan PPID</li>\n                        <li>Mengajukan gugatan ke pengadilan</li>\n                        <li>Mendapatkan ganti rugi atas kesalahan PPID</li>\n                    </ul>\n                </div>\n                <div class=\"col-lg-6\">\n                    <h5 class=\"text-danger\"><i class=\"fas fa-clipboard-check me-2\"></i>Kewajiban Pemohon Informasi</h5>\n                    <ul class=\"mt-3\">\n                        <li>Mengisi formulir permohonan dengan lengkap</li>\n                        <li>Menyertakan identitas diri yang sah</li>\n                        <li>Menggunakan informasi sesuai tujuan yang dinyatakan</li>\n                        <li>Membayar biaya pelayanan (jika ada)</li>\n                        <li>Menjaga kerahasiaan informasi yang dikecualikan</li>\n                    </ul>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Pengajuan Keberatan</h2>\n            <div class=\"profil-content\">\n                <p>Jika pemohon informasi tidak puas dengan keputusan PPID, dapat mengajukan keberatan dalam jangka waktu 30 hari kerja sejak menerima pemberitahuan tertulis dari PPID.</p>\n\n                <div class=\"alert alert-warning mt-3\">\n                    <h6><i class=\"fas fa-exclamation-triangle me-2\"></i>Cara Mengajukan Keberatan:</h6>\n                    <ol>\n                        <li>Mengisi formulir keberatan yang disediakan</li>\n                        <li>Melampirkan alasan keberatan secara jelas</li>\n                        <li>Menyertakan bukti-bukti pendukung</li>\n                        <li>Mengajukan ke PPID yang sama</li>\n                    </ol>\n                </div>\n\n                <p><strong>Waktu Penyelesaian Keberatan:</strong> Maksimal 30 hari kerja sejak keberatan diterima secara lengkap.</p>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Kontak dan Informasi Tambahan</h2>\n            <div class=\"row\">\n                <div class=\"col-md-6\">\n                    <h5><i class=\"fas fa-building text-primary me-2\"></i>Kantor PPID PKTJ</h5>\n                    <p>Jl. Medan Merdeka Barat No. 8<br>\n                    Jakarta Pusat 10110<br>\n                    Indonesia</p>\n                </div>\n                <div class=\"col-md-6\">\n                    <h5><i class=\"fas fa-phone text-success me-2\"></i>Kontak</h5>\n                    <p>Telepon: (021) 3847790<br>\n                    Fax: (021) 3847791<br>\n                    Email: ppid@pktj.dephub.go.id</p>\n                </div>\n            </div>\n\n            <div class=\"mt-4\">\n                <a href=\"/permohonan-informasi\" class=\"btn btn-warning me-3\">\n                    <i class=\"fas fa-file-alt me-2\"></i>Ajukan Permintaan Informasi\n                </a>\n                <a href=\"/profil/kontak\" class=\"btn btn-outline-primary\">\n                    <i class=\"fas fa-map-marker-alt me-2\"></i>Lihat Lokasi Kantor\n                </a>\n            </div>\n        </div>\n<div class=\"premium-box-outer\" style=\"display: inline-block; width: 85%; max-width: 100%; height: 500px; margin: 20px 0; text-align: left; vertical-align: top;\">\n  <div class=\"premium-box-wrapper\" style=\"width: 100%; height: 100%; overflow: hidden; border-radius: 24px; border: 1px solid #e2e8f0; box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1); background: #ffffff;\">\n    <iframe src=\"/preview-dokumen?file=https%3A%2F%2Fdrive.google.com%2Ffile%2Fd%2F1bxbh53yoMpJbS7_pb0PeqDNmbzc3LeRi%2Fview&title=Dokumen+Informasi+Publik&is_blurred=1\" style=\"width: 100%; height: 100%; border: none;\"></iframe>\n  </div>\n</div>',NULL,'',NULL,1,NULL,NULL,'[]','2026-03-25 20:08:13','2026-03-26 00:05:26'),(9,'sop-keberatan','Sop keberatan','SOP Keberatan',NULL,'<div class=\"content-box\">\n            <h2 class=\"section-title\">Dasar Hukum</h2>\n            <div class=\"profil-content\">\n                <p>Standar Operasional Prosedur (SOP) Penanganan Keberatan PPID PKTJ disusun berdasarkan:</p>\n                <ul>\n                    <li>Undang-Undang Nomor 14 Tahun 2008 tentang Keterbukaan Informasi Publik</li>\n                    <li>Peraturan Pemerintah Nomor 61 Tahun 2010 tentang Pelaksanaan Undang-Undang Nomor 14 Tahun 2008</li>\n                    <li>Peraturan Komisi Informasi Nomor 1 Tahun 2021 tentang Standar Layanan Informasi Publik</li>\n                    <li>Keputusan Direktur Jenderal Perhubungan Udara Nomor KP 345 Tahun 2018 tentang SOP PPID PKTJ</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Pengertian Keberatan</h2>\n            <div class=\"profil-content\">\n                <p><strong>Keberatan</strong> adalah hak pemohon informasi untuk mengajukan sanggahan terhadap keputusan PPID yang tidak atau belum sepenuhnya memuaskan pemohon informasi. Keberatan dapat diajukan atas:</p>\n                <ul>\n                    <li>Penolakan permintaan informasi</li>\n                    <li>Tidak dipenuhinya permintaan informasi</li>\n                    <li>Tidak tepat waktu dalam memberikan informasi</li>\n                    <li>Tidak sesuai jumlah biaya yang dikenakan</li>\n                    <li>Tidak sesuai format informasi yang diberikan</li>\n                    <li>Tidak lengkapnya informasi yang diberikan</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"requirements-box\">\n            <h6><i class=\"fas fa-file-signature me-2\"></i>Persyaratan Pengajuan Keberatan</h6>\n            <ul>\n                <li>Formulir keberatan yang telah diisi lengkap</li>\n                <li>Salinan pemberitahuan tertulis keputusan PPID</li>\n                <li>Identitas pemohon informasi (KTP/SIM/Paspor)</li>\n                <li>Alasan keberatan yang jelas dan spesifik</li>\n                <li>Bukti-bukti pendukung keberatan (jika ada)</li>\n                <li>Diajukan dalam jangka waktu 30 hari kerja sejak menerima keputusan PPID</li>\n            </ul>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Alur Prosedur Penanganan Keberatan</h2>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">1</div>\n                <i class=\"fas fa-file-alt\"></i>\n                <h5>Penerimaan Keberatan</h5>\n                <p>PPID menerima keberatan dari pemohon informasi melalui berbagai kanal. Keberatan dicatat dalam register khusus dengan nomor keberatan.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">2</div>\n                <i class=\"fas fa-user-check\"></i>\n                <h5>Verifikasi Kelengkapan</h5>\n                <p>PPID memverifikasi kelengkapan dokumen keberatan. Jika tidak lengkap, PPID memberitahukan kepada pemohon untuk melengkapi dalam waktu 7 hari kerja.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">3</div>\n                <i class=\"fas fa-balance-scale\"></i>\n                <h5>Pembentukan Tim Penanganan</h5>\n                <p>PPID membentuk tim penanganan keberatan yang terdiri dari minimal 3 orang yang memiliki kompetensi dalam penanganan keberatan.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">4</div>\n                <i class=\"fas fa-search\"></i>\n                <h5>Pemeriksaan dan Evaluasi</h5>\n                <p>Tim penanganan melakukan pemeriksaan menyeluruh terhadap keberatan, termasuk mengkaji ulang keputusan awal dan mempertimbangkan alasan keberatan.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">5</div>\n                <i class=\"fas fa-gavel\"></i>\n                <h5>Pengambilan Keputusan</h5>\n                <p>Tim penanganan mengambil keputusan untuk menolak atau mengabulkan keberatan berdasarkan kajian yang dilakukan.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">6</div>\n                <i class=\"fas fa-envelope\"></i>\n                <h5>Pemberitahuan Keputusan</h5>\n                <p>PPID memberitahukan keputusan atas keberatan kepada pemohon dalam waktu maksimal 30 hari kerja sejak keberatan diterima secara lengkap.</p>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Jangka Waktu Penanganan</h2>\n            <div class=\"timeline\">\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">Penerimaan dan Verifikasi</h6>\n                        <p>Maksimal 7 hari kerja untuk memverifikasi kelengkapan dokumen keberatan</p>\n                    </div>\n                </div>\n\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">Pemeriksaan dan Evaluasi</h6>\n                        <p>Maksimal 20 hari kerja untuk melakukan pemeriksaan menyeluruh terhadap keberatan</p>\n                    </div>\n                </div>\n\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">Pengambilan Keputusan</h6>\n                        <p>Maksimal 30 hari kerja sejak keberatan diterima secara lengkap</p>\n                    </div>\n                </div>\n\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">Perpanjangan Jangka Waktu</h6>\n                        <p>Dapat diperpanjang maksimal 30 hari kerja dengan pemberitahuan tertulis</p>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"criteria-list\">\n            <h6>Kriteria Pengabulan Keberatan:</h6>\n            <ul>\n                <li>Informasi yang diminta tidak termasuk informasi yang dikecualikan</li>\n                <li>Alasan penolakan PPID tidak sesuai dengan ketentuan perundang-undangan</li>\n                <li>Informasi yang diminta telah berubah sifatnya menjadi tidak rahasia</li>\n                <li>Kepentingan publik lebih besar daripada kepentingan yang dilindungi</li>\n                <li>Terjadi kesalahan prosedur dalam pengambilan keputusan awal</li>\n                <li>Informasi yang diminta telah diumumkan oleh pihak lain yang berwenang</li>\n            </ul>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Biaya Pelayanan Keberatan</h2>\n            <div class=\"profil-content\">\n                <p>Biaya pelayanan keberatan ditetapkan berdasarkan Standar Biaya Pelayanan Informasi Publik:</p>\n\n                <div class=\"row mt-4\">\n                    <div class=\"col-md-6\">\n                        <h5><i class=\"fas fa-money-bill-wave text-success me-2\"></i>Biaya Gratis</h5>\n                        <ul>\n                            <li>Pengajuan keberatan</li>\n                            <li>Pemeriksaan dan evaluasi keberatan</li>\n                            <li>Pemberitahuan keputusan keberatan</li>\n                        </ul>\n                    </div>\n                    <div class=\"col-md-6\">\n                        <h5><i class=\"fas fa-calculator text-warning me-2\"></i>Biaya Berbayar</h5>\n                        <ul>\n                            <li>Penggandaan dokumen: Rp 500/lembar</li>\n                            <li>Scan dokumen: Rp 1.000/lembar</li>\n                            <li>Media penyimpanan: Rp 10.000/CD</li>\n                            <li>Pengiriman dokumen: sesuai ongkos kirim</li>\n                        </ul>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Hak dan Kewajiban</h2>\n            <div class=\"row\">\n                <div class=\"col-lg-6\">\n                    <h5 class=\"text-primary\"><i class=\"fas fa-user-check me-2\"></i>Hak Pemohon Keberatan</h5>\n                    <ul class=\"mt-3\">\n                        <li>Mendapatkan pemberitahuan tertulis atas keberatan</li>\n                        <li>Mendapatkan alasan yang jelas jika keberatan ditolak</li>\n                        <li>Mengajukan banding ke Komisi Informasi</li>\n                        <li>Mengajukan gugatan ke Pengadilan Tata Usaha Negara</li>\n                        <li>Mendapatkan ganti rugi jika PPID terbukti salah</li>\n                    </ul>\n                </div>\n                <div class=\"col-lg-6\">\n                    <h5 class=\"text-danger\"><i class=\"fas fa-clipboard-check me-2\"></i>Kewajiban PPID</h5>\n                    <ul class=\"mt-3\">\n                        <li>Menyelesaikan keberatan dalam jangka waktu yang ditentukan</li>\n                        <li>Memberikan alasan yang jelas dan dapat dipertanggungjawabkan</li>\n                        <li>Menyimpan dokumen keberatan sebagai arsip</li>\n                        <li>Melaporkan penanganan keberatan kepada atasan</li>\n                        <li>Menindaklanjuti keputusan yang diambil</li>\n                    </ul>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Pengajuan Sengketa</h2>\n            <div class=\"profil-content\">\n                <p>Jika keberatan ditolak oleh PPID, pemohon dapat mengajukan sengketa informasi ke Komisi Informasi dalam waktu 30 hari kerja sejak menerima keputusan PPID.</p>\n\n                <div class=\"alert alert-warning mt-3\">\n                    <h6><i class=\"fas fa-exclamation-triangle me-2\"></i>Cara Mengajukan Sengketa:</h6>\n                    <ol>\n                        <li>Mengisi formulir sengketa yang disediakan Komisi Informasi</li>\n                        <li>Melampirkan salinan keberatan dan keputusan PPID</li>\n                        <li>Menyertakan alasan sengketa secara jelas</li>\n                        <li>Mengajukan ke Komisi Informasi setempat</li>\n                    </ol>\n                </div>\n\n                <p><strong>Waktu Penyelesaian Sengketa:</strong> Maksimal 60 hari kerja sejak sengketa diterima secara lengkap.</p>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Formulir dan Kontak</h2>\n            <div class=\"row\">\n                <div class=\"col-md-6\">\n                    <h5><i class=\"fas fa-download text-primary me-2\"></i>Download Formulir</h5>\n                    <p>Formulir keberatan dapat didownload melalui:</p>\n                    <ul>\n                        <li><a href=\"#\" class=\"text-decoration-none\">Website PPID PKTJ</a></li>\n                        <li><a href=\"#\" class=\"text-decoration-none\">Portal Kemenkominfo</a></li>\n                        <li><a href=\"#\" class=\"text-decoration-none\">Datang langsung ke kantor PPID</a></li>\n                    </ul>\n                </div>\n                <div class=\"col-md-6\">\n                    <h5><i class=\"fas fa-building text-success me-2\"></i>Kontak PPID</h5>\n                    <p>Jl. Medan Merdeka Barat No. 8<br>\n                    Jakarta Pusat 10110<br>\n                    Indonesia</p>\n                    <p><strong>Telepon:</strong> (021) 3847790<br>\n                    <strong>Email:</strong> ppid@pktj.dephub.go.id</p>\n                </div>\n            </div>\n\n            <div class=\"mt-4\">\n                <a href=\"/permohonan-informasi\" class=\"btn btn-warning me-3\">\n                    <i class=\"fas fa-file-alt me-2\"></i>Ajukan Keberatan\n                </a>\n                <a href=\"/profil/kontak\" class=\"btn btn-outline-primary\">\n                    <i class=\"fas fa-map-marker-alt me-2\"></i>Lihat Lokasi Kantor\n                </a>\n            </div>\n        </div>\n<div class=\"premium-box-outer\" style=\"display: inline-block; width: 85%; max-width: 100%; height: 500px; margin: 20px 0; text-align: left; vertical-align: top;\">\n  <div class=\"premium-box-wrapper\" style=\"width: 100%; height: 100%; overflow: hidden; border-radius: 24px; border: 1px solid #e2e8f0; box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1); background: #ffffff;\">\n    <iframe src=\"/preview-dokumen?file=https%3A%2F%2Fdrive.google.com%2Ffile%2Fd%2F1bxbh53yoMpJbS7_pb0PeqDNmbzc3LeRi%2Fview&title=Dokumen+Informasi+Publik&is_blurred=1\" style=\"width: 100%; height: 100%; border: none;\"></iframe>\n  </div>\n</div>',NULL,'',NULL,1,NULL,NULL,'[]','2026-03-25 20:08:13','2026-03-26 00:05:26'),(10,'sop-sengketa','Sop sengketa','SOP Sengketa Informasi',NULL,'<div class=\"content-box\">\n            <h2 class=\"section-title\">Dasar Hukum</h2>\n            <div class=\"profil-content\">\n                <p>Standar Operasional Prosedur (SOP) Pengajuan Sengketa Informasi Publik PPID PKTJ disusun berdasarkan:</p>\n                <ul>\n                    <li>Undang-Undang Nomor 14 Tahun 2008 tentang Keterbukaan Informasi Publik</li>\n                    <li>Peraturan Pemerintah Nomor 61 Tahun 2010 tentang Pelaksanaan Undang-Undang Nomor 14 Tahun 2008</li>\n                    <li>Undang-Undang Nomor 51 Tahun 2009 tentang Peradilan Tata Usaha Negara</li>\n                    <li>Peraturan Komisi Informasi Nomor 1 Tahun 2021 tentang Standar Layanan Informasi Publik</li>\n                    <li>Keputusan Direktur Jenderal Perhubungan Udara Nomor KP 345 Tahun 2018 tentang SOP PPID PKTJ</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Pengertian Sengketa Informasi</h2>\n            <div class=\"profil-content\">\n                <p><strong>Sengketa Informasi</strong> adalah sengketa yang timbul dalam hal terjadinya perselisihan antara badan publik dengan pemohon informasi atau antara badan publik dengan Komisi Informasi terkait pelaksanaan Undang-Undang Keterbukaan Informasi Publik.</p>\n\n                <p>Sengketa informasi dapat diajukan jika keberatan kepada PPID telah ditolak atau dalam hal terjadi sengketa antar badan publik. Sengketa informasi diselesaikan melalui mekanisme mediasi oleh Komisi Informasi atau melalui pengadilan Tata Usaha Negara.</p>\n            </div>\n        </div>\n\n        <div class=\"requirements-box\">\n            <h6><i class=\"fas fa-file-signature me-2\"></i>Persyaratan Pengajuan Sengketa</h6>\n            <ul>\n                <li>Formulir sengketa informasi yang telah diisi lengkap</li>\n                <li>Salinan keputusan PPID atas keberatan</li>\n                <li>Salinan formulir permintaan informasi dan keberatan</li>\n                <li>Identitas pemohon (KTP/SIM/Paspor)</li>\n                <li>Bukti-bukti pendukung sengketa</li>\n                <li>Diajukan dalam jangka waktu 30 hari kerja sejak menerima keputusan PPID</li>\n            </ul>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Mekanisme Penyelesaian Sengketa</h2>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">1</div>\n                <i class=\"fas fa-balance-scale\"></i>\n                <h5>Mediasi Komisi Informasi</h5>\n                <p>Sengketa informasi pertama-tama diselesaikan melalui mediasi oleh Komisi Informasi. Mediasi dilakukan untuk mencapai kesepakatan bersama antara para pihak.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">2</div>\n                <i class=\"fas fa-gavel\"></i>\n                <h5>Ajudikasi Komisi Informasi</h5>\n                <p>Jika mediasi tidak mencapai kesepakatan, Komisi Informasi akan melakukan ajudikasi untuk memutus sengketa berdasarkan fakta dan bukti yang ada.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">3</div>\n                <i class=\"fas fa-university\"></i>\n                <h5>Banding ke Pengadilan</h5>\n                <p>Para pihak dapat mengajukan banding terhadap putusan Komisi Informasi ke Pengadilan Tata Usaha Negara dalam waktu 14 hari kerja.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">4</div>\n                <i class=\"fas fa-check-circle\"></i>\n                <h5>Eksekusi Putusan</h5>\n                <p>Putusan yang telah berkekuatan hukum tetap wajib dilaksanakan oleh para pihak yang bersengketa.</p>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Jangka Waktu Penyelesaian</h2>\n            <div class=\"timeline\">\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">Proses Mediasi</h6>\n                        <p>Maksimal 30 hari kerja sejak sengketa diterima Komisi Informasi</p>\n                    </div>\n                </div>\n\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">Proses Ajudikasi</h6>\n                        <p>Maksimal 60 hari kerja sejak sengketa diterima Komisi Informasi</p>\n                    </div>\n                </div>\n\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">Pengajuan Banding</h6>\n                        <p>Maksimal 14 hari kerja sejak menerima putusan Komisi Informasi</p>\n                    </div>\n                </div>\n\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">Proses di Pengadilan</h6>\n                        <p>Maksimal 90 hari kerja untuk tingkat pertama, dapat diperpanjang</p>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"court-info\">\n            <h6><i class=\"fas fa-landmark me-2\"></i>Komisi Informasi Pusat</h6>\n            <ul>\n                <li>Jl. Rasuna Said Kav. C1 No. 1, Kuningan, Jakarta Selatan</li>\n                <li>Telepon: (021) 50827100</li>\n                <li>Fax: (021) 50827101</li>\n                <li>Email: info@komisiinformasi.go.id</li>\n                <li>Website: www.komisiinformasi.go.id</li>\n            </ul>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Biaya Sengketa</h2>\n            <div class=\"profil-content\">\n                <p>Biaya penyelesaian sengketa informasi publik ditetapkan sebagai berikut:</p>\n\n                <div class=\"row mt-4\">\n                    <div class=\"col-md-6\">\n                        <h5><i class=\"fas fa-money-bill-wave text-success me-2\"></i>Biaya Gratis</h5>\n                        <ul>\n                            <li>Pengajuan sengketa ke Komisi Informasi</li>\n                            <li>Proses mediasi oleh Komisi Informasi</li>\n                            <li>Proses ajudikasi oleh Komisi Informasi</li>\n                        </ul>\n                    </div>\n                    <div class=\"col-md-6\">\n                        <h5><i class=\"fas fa-calculator text-warning me-2\"></i>Biaya Pengadilan</h5>\n                        <ul>\n                            <li>Pengajuan banding ke PTUN: Rp 500.000,-</li>\n                            <li>Biaya materai dan administrasi</li>\n                            <li>Biaya saksi dan ahli (jika diperlukan)</li>\n                            <li>Biaya pengacara (jika menggunakan jasa)</li>\n                        </ul>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Hak dan Kewajiban Para Pihak</h2>\n            <div class=\"row\">\n                <div class=\"col-lg-6\">\n                    <h5 class=\"text-primary\"><i class=\"fas fa-user-check me-2\"></i>Hak Pemohon</h5>\n                    <ul class=\"mt-3\">\n                        <li>Mendapatkan putusan yang adil dan objektif</li>\n                        <li>Mendapatkan informasi yang diminta jika sengketa dikabulkan</li>\n                        <li>Mengajukan banding jika tidak puas dengan putusan</li>\n                        <li>Mendapatkan ganti rugi jika badan publik terbukti salah</li>\n                        <li>Mendapatkan bantuan hukum (jika memenuhi syarat)</li>\n                    </ul>\n                </div>\n                <div class=\"col-lg-6\">\n                    <h5 class=\"text-danger\"><i class=\"fas fa-building me-2\"></i>Kewajiban Badan Publik</h5>\n                    <ul class=\"mt-3\">\n                        <li>Menyampaikan jawaban atas sengketa dalam waktu yang ditentukan</li>\n                        <li>Menyediakan bukti-bukti pendukung dalam proses sengketa</li>\n                        <li>Melaksanakan putusan yang telah berkekuatan hukum tetap</li>\n                        <li>Menyampaikan laporan pelaksanaan putusan</li>\n                        <li>Membayar ganti rugi jika terbukti melanggar ketentuan</li>\n                    </ul>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"important-note\">\n            <h6><i class=\"fas fa-exclamation-triangle me-2\"></i>PENTING</h6>\n            <p>Sengketa informasi merupakan mekanisme terakhir dalam penyelesaian perselisihan informasi publik. Sebelum mengajukan sengketa, pastikan telah melalui proses keberatan internal terlebih dahulu. Sengketa yang diajukan tanpa melalui proses keberatan internal akan ditolak.</p>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Cara Mengajukan Sengketa</h2>\n            <div class=\"profil-content\">\n                <p>Untuk mengajukan sengketa informasi publik, ikuti langkah-langkah berikut:</p>\n\n                <div class=\"row mt-4\">\n                    <div class=\"col-md-6\">\n                        <h5><i class=\"fas fa-list-check text-primary me-2\"></i>Persiapan Dokumen</h5>\n                        <ol>\n                            <li>Kumpulkan semua dokumen yang diperlukan</li>\n                            <li>Isi formulir sengketa dengan lengkap</li>\n                            <li>Siapkan alasan sengketa yang jelas</li>\n                            <li>Kumpulkan bukti-bukti pendukung</li>\n                        </ol>\n                    </div>\n                    <div class=\"col-md-6\">\n                        <h5><i class=\"fas fa-paper-plane text-success me-2\"></i>Pengajuan Sengketa</h5>\n                        <ol>\n                            <li>Ajukan ke Komisi Informasi setempat</li>\n                            <li>Serahkan dokumen secara langsung atau online</li>\n                            <li>Tunggu pemberitahuan pendaftaran sengketa</li>\n                            <li>Ikuti proses mediasi/ajudikasi</li>\n                        </ol>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Kontak dan Informasi Tambahan</h2>\n            <div class=\"row\">\n                <div class=\"col-md-6\">\n                    <h5><i class=\"fas fa-landmark text-primary me-2\"></i>Komisi Informasi</h5>\n                    <p>Jl. Rasuna Said Kav. C1 No. 1<br>\n                    Kuningan, Jakarta Selatan 12910<br>\n                    Indonesia</p>\n                </div>\n                <div class=\"col-md-6\">\n                    <h5><i class=\"fas fa-phone text-success me-2\"></i>Kontak</h5>\n                    <p>Telepon: (021) 50827100<br>\n                    Fax: (021) 50827101<br>\n                    Email: info@komisiinformasi.go.id</p>\n                </div>\n            </div>\n\n            <div class=\"mt-4\">\n                <a href=\"https://www.komisiinformasi.go.id/\" target=\"_blank\" class=\"btn btn-warning me-3\">\n                    <i class=\"fas fa-external-link-alt me-2\"></i>Website Komisi Informasi\n                </a>\n                <a href=\"/prosedur/sop-penanganan-keberatan\" class=\"btn btn-outline-primary\">\n                    <i class=\"fas fa-arrow-left me-2\"></i>Kembali ke SOP Keberatan\n                </a>\n            </div>\n        </div>\n<div class=\"premium-box-outer\" style=\"display: inline-block; width: 85%; max-width: 100%; height: 500px; margin: 20px 0; text-align: left; vertical-align: top;\">\n  <div class=\"premium-box-wrapper\" style=\"width: 100%; height: 100%; overflow: hidden; border-radius: 24px; border: 1px solid #e2e8f0; box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1); background: #ffffff;\">\n    <iframe src=\"/preview-dokumen?file=https%3A%2F%2Fdrive.google.com%2Ffile%2Fd%2F1bxbh53yoMpJbS7_pb0PeqDNmbzc3LeRi%2Fview&title=Dokumen+Informasi+Publik&is_blurred=1\" style=\"width: 100%; height: 100%; border: none;\"></iframe>\n  </div>\n</div>',NULL,'',NULL,1,NULL,NULL,'[]','2026-03-25 20:08:13','2026-03-26 00:05:26'),(11,'sop-penetapan','Sop penetapan','SOP Penetapan DIP',NULL,'<div class=\"content-box\">\n            <h2 class=\"section-title\">Dasar Hukum</h2>\n            <div class=\"profil-content\">\n                <p>Standar Operasional Prosedur (SOP) Penetapan dan Pemutakhiran Daftar Informasi Publik PPID PKTJ disusun berdasarkan:</p>\n                <ul>\n                    <li>Undang-Undang Nomor 14 Tahun 2008 tentang Keterbukaan Informasi Publik</li>\n                    <li>Peraturan Pemerintah Nomor 61 Tahun 2010 tentang Pelaksanaan Undang-Undang Nomor 14 Tahun 2008</li>\n                    <li>Peraturan Komisi Informasi Nomor 1 Tahun 2021 tentang Standar Layanan Informasi Publik</li>\n                    <li>Keputusan Direktur Jenderal Perhubungan Udara Nomor KP 345 Tahun 2018 tentang SOP PPID PKTJ</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Pengertian Daftar Informasi Publik</h2>\n            <div class=\"profil-content\">\n                <p><strong>Daftar Informasi Publik</strong> adalah katalog yang berisi sekumpulan informasi yang dapat diakses oleh publik dan disusun secara sistematis. Daftar informasi publik merupakan sarana bagi pemohon informasi untuk mengetahui jenis-jenis informasi yang tersedia dan dapat diminta.</p>\n\n                <p>Daftar informasi publik wajib disusun oleh setiap badan publik dan harus selalu diperbaharui sesuai dengan perkembangan informasi yang ada. Daftar ini harus mudah diakses dan dapat diperoleh secara gratis.</p>\n            </div>\n        </div>\n\n        <div class=\"category-list\">\n            <h6>Kategori Informasi dalam Daftar:</h6>\n            <ul>\n                <li>Informasi yang wajib disediakan dan diumumkan secara berkala</li>\n                <li>Informasi yang wajib tersedia setiap saat</li>\n                <li>Informasi yang wajib tersedia atas permintaan</li>\n                <li>Informasi yang dikecualikan dari keterbukaan</li>\n                <li>Informasi yang dapat diakses dengan permintaan tertentu</li>\n                <li>Informasi tentang kegiatan dan program badan publik</li>\n                <li>Informasi tentang keuangan dan anggaran</li>\n                <li>Informasi tentang peraturan dan kebijakan</li>\n            </ul>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Alur Prosedur Penetapan Daftar Informasi</h2>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">1</div>\n                <i class=\"fas fa-search\"></i>\n                <h5>Inventarisasi Informasi</h5>\n                <p>PPID melakukan inventarisasi seluruh informasi yang dimiliki oleh badan publik. Inventarisasi dilakukan secara menyeluruh pada semua unit kerja.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">2</div>\n                <i class=\"fas fa-tags\"></i>\n                <h5>Klasifikasi Informasi</h5>\n                <p>Informasi yang telah diinventarisasi diklasifikasikan berdasarkan jenis, kategori, dan tingkat keterbukaannya sesuai ketentuan perundang-undangan.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">3</div>\n                <i class=\"fas fa-edit\"></i>\n                <h5>Penyusunan Daftar</h5>\n                <p>PPID menyusun daftar informasi publik dalam format yang mudah dipahami dan diakses oleh publik.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">4</div>\n                <i class=\"fas fa-check-circle\"></i>\n                <h5>Validasi dan Verifikasi</h5>\n                <p>Daftar informasi diverifikasi oleh pimpinan badan publik untuk memastikan keakuratan dan kelengkapan informasi.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">5</div>\n                <i class=\"fas fa-bullhorn\"></i>\n                <h5>Penetapan dan Pengumuman</h5>\n                <p>Daftar informasi ditetapkan melalui keputusan pimpinan dan diumumkan melalui berbagai kanal komunikasi.</p>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Prosedur Pemutakhiran Daftar</h2>\n            <div class=\"timeline\">\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">Monitoring Berkala</h6>\n                        <p>PPID melakukan monitoring terhadap perubahan informasi setiap 3 bulan sekali</p>\n                    </div>\n                </div>\n\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">Identifikasi Perubahan</h6>\n                        <p>Mengidentifikasi informasi baru, perubahan, atau penghapusan informasi</p>\n                    </div>\n                </div>\n\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">Update Daftar</h6>\n                        <p>Memperbaharui daftar informasi sesuai dengan perubahan yang terjadi</p>\n                    </div>\n                </div>\n\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">Verifikasi Update</h6>\n                        <p>Melakukan verifikasi terhadap daftar yang telah diperbaharui</p>\n                    </div>\n                </div>\n\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">Pengumuman Update</h6>\n                        <p>Mengumumkan daftar informasi yang telah diperbaharui kepada publik</p>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"requirements-box\">\n            <h6><i class=\"fas fa-file-signature me-2\"></i>Persyaratan Format Daftar Informasi</h6>\n            <ul>\n                <li>Format daftar harus mudah dibaca dan dipahami</li>\n                <li>Menggunakan bahasa Indonesia yang baku</li>\n                <li>Dilengkapi dengan indeks dan sistem navigasi</li>\n                <li>Tersedia dalam format cetak dan digital</li>\n                <li>Mencantumkan tanggal pembuatan dan pemutakhiran</li>\n                <li>Dilengkapi dengan penjelasan singkat setiap jenis informasi</li>\n                <li>Mencantumkan unit kerja yang mengelola informasi</li>\n                <li>Dilengkapi dengan kontak untuk mendapatkan informasi</li>\n            </ul>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Tanggung Jawab Unit Kerja</h2>\n            <div class=\"profil-content\">\n                <p>Dalam penetapan dan pemutakhiran daftar informasi publik, setiap unit kerja memiliki tanggung jawab sebagai berikut:</p>\n\n                <div class=\"row mt-4\">\n                    <div class=\"col-md-6\">\n                        <h5><i class=\"fas fa-users text-primary me-2\"></i>Unit Kerja Teknis</h5>\n                        <ul>\n                            <li>Menyediakan data dan informasi yang dikelola</li>\n                            <li>Melakukan inventarisasi informasi internal</li>\n                            <li>Menyampaikan perubahan informasi kepada PPID</li>\n                            <li>Memverifikasi keakuratan informasi dalam daftar</li>\n                        </ul>\n                    </div>\n                    <div class=\"col-md-6\">\n                        <h5><i class=\"fas fa-user-tie text-success me-2\"></i>PPID</h5>\n                        <ul>\n                            <li>Menyusun dan mengelola daftar informasi publik</li>\n                            <li>Berkordinasi dengan unit kerja terkait</li>\n                            <li>Melakukan pemutakhiran daftar secara berkala</li>\n                            <li>Menyediakan akses mudah terhadap daftar informasi</li>\n                        </ul>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Sistem Pengelolaan Daftar</h2>\n            <div class=\"profil-content\">\n                <p>PPID PKTJ menggunakan sistem pengelolaan daftar informasi publik yang terintegrasi dan dapat diakses melalui:</p>\n\n                <div class=\"row mt-4\">\n                    <div class=\"col-md-6\">\n                        <h5><i class=\"fas fa-globe text-primary me-2\"></i>Media Online</h5>\n                        <ul>\n                            <li>Website resmi PPID PKTJ</li>\n                            <li>Portal data terbuka</li>\n                            <li>Aplikasi mobile (dalam pengembangan)</li>\n                            <li>Database terintegrasi</li>\n                        </ul>\n                    </div>\n                    <div class=\"col-md-6\">\n                        <h5><i class=\"fas fa-building text-success me-2\"></i>Media Offline</h5>\n                        <ul>\n                            <li>Buku daftar informasi cetak</li>\n                            <li>Papan informasi di kantor</li>\n                            <li>Brosur dan leaflet</li>\n                            <li>CD/DVD data informasi</li>\n                        </ul>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"important-note\">\n            <h6><i class=\"fas fa-exclamation-triangle me-2\"></i>PENTING</h6>\n            <p>Daftar informasi publik harus selalu diperbaharui secara berkala minimal setiap 6 bulan sekali atau setiap kali terjadi perubahan signifikan. Keterlambatan pemutakhiran daftar dapat dikenai sanksi sesuai ketentuan perundang-undangan.</p>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Monitoring dan Evaluasi</h2>\n            <div class=\"profil-content\">\n                <p>PPID melakukan monitoring dan evaluasi terhadap efektivitas daftar informasi publik melalui:</p>\n                <ul>\n                    <li>Survei kepuasan pengguna daftar informasi</li>\n                    <li>Analisis jumlah permintaan informasi dari daftar</li>\n                    <li>Evaluasi kelengkapan dan keakuratan daftar</li>\n                    <li>Penilaian kemudahan akses daftar informasi</li>\n                    <li>Laporan periodik kepada pimpinan</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Kontak dan Informasi Tambahan</h2>\n            <div class=\"row\">\n                <div class=\"col-md-6\">\n                    <h5><i class=\"fas fa-building text-primary me-2\"></i>Kantor PPID PKTJ</h5>\n                    <p>Jl. Medan Merdeka Barat No. 8<br>\n                    Jakarta Pusat 10110<br>\n                    Indonesia</p>\n                </div>\n                <div class=\"col-md-6\">\n                    <h5><i class=\"fas fa-phone text-success me-2\"></i>Kontak</h5>\n                    <p>Telepon: (021) 3847790<br>\n                    Fax: (021) 3847791<br>\n                    Email: ppid@pktj.dephub.go.id</p>\n                </div>\n            </div>\n\n            <div class=\"mt-4\">\n                <a href=\"/layanan-informasi/daftar\" class=\"btn btn-warning me-3\">\n                    <i class=\"fas fa-list-alt me-2\"></i>Lihat Daftar Informasi Publik\n                </a>\n                <a href=\"/profil/kontak\" class=\"btn btn-outline-primary\">\n                    <i class=\"fas fa-map-marker-alt me-2\"></i>Lihat Lokasi Kantor\n                </a>\n            </div>\n        </div>\n<div class=\"premium-box-outer\" style=\"display: inline-block; width: 85%; max-width: 100%; height: 500px; margin: 20px 0; text-align: left; vertical-align: top;\">\n  <div class=\"premium-box-wrapper\" style=\"width: 100%; height: 100%; overflow: hidden; border-radius: 24px; border: 1px solid #e2e8f0; box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1); background: #ffffff;\">\n    <iframe src=\"/preview-dokumen?file=https%3A%2F%2Fdrive.google.com%2Ffile%2Fd%2F1bxbh53yoMpJbS7_pb0PeqDNmbzc3LeRi%2Fview&title=Dokumen+Informasi+Publik&is_blurred=1\" style=\"width: 100%; height: 100%; border: none;\"></iframe>\n  </div>\n</div>',NULL,'',NULL,1,NULL,NULL,'[]','2026-03-25 20:08:13','2026-03-26 00:05:26'),(12,'sop-pengujian','Sop pengujian','SOP Pengujian Konsekuensi',NULL,'<div class=\"content-box\">\n            <h2 class=\"section-title\">Dasar Hukum</h2>\n            <div class=\"profil-content\">\n                <p>Standar Operasional Prosedur (SOP) Pengujian Konsekuensi PPID PKTJ disusun berdasarkan:</p>\n                <ul>\n                    <li>Undang-Undang Nomor 14 Tahun 2008 tentang Keterbukaan Informasi Publik</li>\n                    <li>Peraturan Pemerintah Nomor 61 Tahun 2010 tentang Pelaksanaan Undang-Undang Nomor 14 Tahun 2008</li>\n                    <li>Peraturan Komisi Informasi Nomor 1 Tahun 2021 tentang Standar Layanan Informasi Publik</li>\n                    <li>Keputusan Direktur Jenderal Perhubungan Udara Nomor KP 345 Tahun 2018 tentang SOP PPID PKTJ</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Pengertian Pengujian Konsekuensi</h2>\n            <div class=\"profil-content\">\n                <p><strong>Pengujian Konsekuensi</strong> adalah proses evaluasi mendalam terhadap potensi dampak negatif yang mungkin timbul apabila informasi yang dikecualikan dari keterbukaan informasi publik dibuka kepada masyarakat. Pengujian ini dilakukan untuk menentukan apakah alasan pengecualian informasi masih relevan atau sudah tidak berlaku.</p>\n\n                <p>Pengujian konsekuensi bersifat objektif dan dilakukan secara sistematis berdasarkan kriteria yang telah ditentukan dalam peraturan perundang-undangan. Hasil pengujian konsekuensi menjadi dasar bagi PPID dalam mengambil keputusan untuk membuka atau menolak informasi.</p>\n            </div>\n        </div>\n\n        <div class=\"criteria-box\">\n            <h6><i class=\"fas fa-list-check me-2\"></i>Kapan Pengujian Konsekuensi Dilakukan</h6>\n            <ul>\n                <li>Informasi yang dikecualikan berdasarkan Pasal 17 UU KIP akan dibuka</li>\n                <li>Informasi telah berubah sifatnya menjadi tidak rahasia</li>\n                <li>Kepentingan publik lebih besar daripada kepentingan yang dilindungi</li>\n                <li>Informasi telah diumumkan oleh pihak lain yang berwenang</li>\n                <li>Informasi telah menjadi pengetahuan umum</li>\n                <li>Ada perintah pengadilan untuk membuka informasi</li>\n                <li>Permintaan ulang terhadap informasi yang pernah ditolak</li>\n            </ul>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Alur Prosedur Pengujian Konsekuensi</h2>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">1</div>\n                <i class=\"fas fa-file-alt\"></i>\n                <h5>Penerimaan Permintaan</h5>\n                <p>PPID menerima permintaan informasi atau permintaan ulang terhadap informasi yang pernah ditolak. Permintaan dicatat dalam register khusus.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">2</div>\n                <i class=\"fas fa-users\"></i>\n                <h5>Pembentukan Tim Penguji</h5>\n                <p>PPID membentuk tim penguji yang terdiri dari minimal 3 orang yang memiliki kompetensi di bidangnya. Tim diketuai oleh pejabat PPID.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">3</div>\n                <i class=\"fas fa-search\"></i>\n                <h5>Analisis Awal</h5>\n                <p>Tim penguji melakukan analisis awal terhadap informasi yang diminta, termasuk mengkaji alasan penolakan sebelumnya dan konteks permintaan.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">4</div>\n                <i class=\"fas fa-balance-scale\"></i>\n                <h5>Pengujian Konsekuensi</h5>\n                <p>Tim melakukan pengujian konsekuensi berdasarkan kriteria yang telah ditentukan. Pengujian dilakukan secara obyektif dan sistematis.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">5</div>\n                <i class=\"fas fa-gavel\"></i>\n                <h5>Pengambilan Keputusan</h5>\n                <p>Tim mengambil keputusan untuk membuka atau tetap menolak informasi berdasarkan hasil pengujian konsekuensi.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">6</div>\n                <i class=\"fas fa-envelope\"></i>\n                <h5>Pemberitahuan Keputusan</h5>\n                <p>PPID memberitahukan keputusan kepada pemohon informasi dengan alasan yang jelas dan dapat dipertanggungjawabkan.</p>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Kriteria Pengujian Konsekuensi</h2>\n            <div class=\"assessment-matrix\">\n                <h6>Kriteria yang Dinilai dalam Pengujian Konsekuensi:</h6>\n                <ul>\n                    <li>Dampak terhadap keamanan negara dan stabilitas nasional</li>\n                    <li>Risiko terhadap kepentingan ekonomi nasional</li>\n                    <li>Potensi pelanggaran hak privasi individu</li>\n                    <li>Dampak terhadap proses peradilan yang sedang berlangsung</li>\n                    <li>Risiko terhadap keselamatan masyarakat</li>\n                    <li>Dampak terhadap rahasia dagang dan kekayaan intelektual</li>\n                    <li>Konsekuensi terhadap hubungan internasional</li>\n                    <li>Potensi gangguan terhadap fungsi pengawasan</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Metode Pengujian</h2>\n            <div class=\"timeline\">\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">1. Kajian Internal</h6>\n                        <p>Mengkaji dampak pembukaan informasi terhadap kepentingan internal badan publik</p>\n                    </div>\n                </div>\n\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">2. Kajian Eksternal</h6>\n                        <p>Mengkaji dampak pembukaan informasi terhadap kepentingan publik dan pihak terkait</p>\n                    </div>\n                </div>\n\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">3. Analisis Risiko</h6>\n                        <p>Melakukan analisis risiko terhadap berbagai skenario pembukaan informasi</p>\n                    </div>\n                </div>\n\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">4. Konsultasi</h6>\n                        <p>Berkonsultasi dengan unit kerja terkait dan ahli yang kompeten</p>\n                    </div>\n                </div>\n\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">5. Pembobotan</h6>\n                        <p>Memberikan bobot pada setiap aspek konsekuensi yang diidentifikasi</p>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Komposisi Tim Penguji</h2>\n            <div class=\"profil-content\">\n                <p>Tim penguji konsekuensi terdiri dari:</p>\n                <ul>\n                    <li><strong>Ketua Tim:</strong> Pejabat PPID yang memiliki kompetensi di bidang keterbukaan informasi</li>\n                    <li><strong>Sekretaris:</strong> Staf PPID yang bertugas mencatat dan mendokumentasikan proses pengujian</li>\n                    <li><strong>Anggota:</strong> Minimal 2 orang dari unit kerja yang mengelola informasi atau ahli terkait</li>\n                    <li><strong>Observer:</strong> Perwakilan dari unit kerja terkait (jika diperlukan)</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Jangka Waktu Pengujian</h2>\n            <div class=\"profil-content\">\n                <p>Jangka waktu pelaksanaan pengujian konsekuensi:</p>\n                <ul>\n                    <li><strong>Pembentukan Tim:</strong> Maksimal 3 hari kerja sejak permintaan diterima</li>\n                    <li><strong>Proses Pengujian:</strong> Maksimal 10 hari kerja</li>\n                    <li><strong>Pengambilan Keputusan:</strong> Maksimal 7 hari kerja setelah pengujian selesai</li>\n                    <li><strong>Total Jangka Waktu:</strong> Maksimal 20 hari kerja</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"important-note\">\n            <h6><i class=\"fas fa-exclamation-triangle me-2\"></i>PENTING</h6>\n            <p>Pengujian konsekuensi harus dilakukan secara obyektif dan profesional. Hasil pengujian harus dapat dipertanggungjawabkan secara hukum. Tim penguji dilarang menerima intervensi dari pihak manapun yang dapat mempengaruhi obyektivitas pengujian.</p>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Dokumentasi Pengujian</h2>\n            <div class=\"profil-content\">\n                <p>PPID wajib mendokumentasikan seluruh proses pengujian konsekuensi dengan mencatat:</p>\n                <ul>\n                    <li>Identitas tim penguji dan tanggal pengujian</li>\n                    <li>Ringkasan permintaan informasi</li>\n                    <li>Hasil analisis awal dan kajian mendalam</li>\n                    <li>Argumentasi pro dan kontra pembukaan informasi</li>\n                    <li>Keputusan akhir dan alasan yang mendasarinya</li>\n                    <li>Tanda tangan seluruh anggota tim penguji</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Pelaporan dan Evaluasi</h2>\n            <div class=\"profil-content\">\n                <p>PPID wajib:</p>\n                <ul>\n                    <li>Melaporkan hasil pengujian konsekuensi kepada pimpinan badan publik</li>\n                    <li>Menyimpan dokumentasi pengujian sebagai arsip penting</li>\n                    <li>Melakukan evaluasi terhadap proses pengujian secara berkala</li>\n                    <li>Meningkatkan kapasitas tim penguji melalui pelatihan</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Kontak dan Informasi Tambahan</h2>\n            <div class=\"row\">\n                <div class=\"col-md-6\">\n                    <h5><i class=\"fas fa-building text-primary me-2\"></i>Kantor PPID PKTJ</h5>\n                    <p>Jl. Medan Merdeka Barat No. 8<br>\n                    Jakarta Pusat 10110<br>\n                    Indonesia</p>\n                </div>\n                <div class=\"col-md-6\">\n                    <h5><i class=\"fas fa-phone text-success me-2\"></i>Kontak</h5>\n                    <p>Telepon: (021) 3847790<br>\n                    Fax: (021) 3847791<br>\n                    Email: ppid@pktj.dephub.go.id</p>\n                </div>\n            </div>\n\n            <div class=\"mt-4\">\n                <a href=\"/informasi-publik/dikecualikan\" class=\"btn btn-warning me-3\">\n                    <i class=\"fas fa-shield-alt me-2\"></i>Lihat Informasi Dikecualikan\n                </a>\n                <a href=\"/profil/kontak\" class=\"btn btn-outline-primary\">\n                    <i class=\"fas fa-map-marker-alt me-2\"></i>Lihat Lokasi Kantor\n                </a>\n            </div>\n        </div>\n<div class=\"premium-box-outer\" style=\"display: inline-block; width: 85%; max-width: 100%; height: 500px; margin: 20px 0; text-align: left; vertical-align: top;\">\n  <div class=\"premium-box-wrapper\" style=\"width: 100%; height: 100%; overflow: hidden; border-radius: 24px; border: 1px solid #e2e8f0; box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1); background: #ffffff;\">\n    <iframe src=\"/preview-dokumen?file=https%3A%2F%2Fdrive.google.com%2Ffile%2Fd%2F1bxbh53yoMpJbS7_pb0PeqDNmbzc3LeRi%2Fview&title=Dokumen+Informasi+Publik&is_blurred=1\" style=\"width: 100%; height: 100%; border: none;\"></iframe>\n  </div>\n</div>',NULL,'',NULL,1,NULL,NULL,'[]','2026-03-25 20:08:13','2026-03-26 00:05:26'),(13,'sop-pendokumentasian','Sop pendokumentasian','SOP Pendokumentasian',NULL,'<div class=\"content-box\">\n            <h2 class=\"section-title\">Dasar Hukum</h2>\n            <div class=\"profil-content\">\n                <p>Standar Operasional Prosedur (SOP) Pendokumentasian Informasi Publik PPID PKTJ disusun berdasarkan:</p>\n                <ul>\n                    <li>Undang-Undang Nomor 14 Tahun 2008 tentang Keterbukaan Informasi Publik</li>\n                    <li>Peraturan Pemerintah Nomor 61 Tahun 2010 tentang Pelaksanaan Undang-Undang Nomor 14 Tahun 2008</li>\n                    <li>Undang-Undang Nomor 43 Tahun 2009 tentang Kearsipan</li>\n                    <li>Peraturan Komisi Informasi Nomor 1 Tahun 2021 tentang Standar Layanan Informasi Publik</li>\n                    <li>Keputusan Direktur Jenderal Perhubungan Udara Nomor KP 345 Tahun 2018 tentang SOP PPID PKTJ</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Pengertian Pendokumentasian</h2>\n            <div class=\"profil-content\">\n                <p><strong>Pendokumentasian Informasi Publik</strong> adalah proses pengumpulan, pengolahan, penyimpanan, dan pengelolaan dokumen serta informasi yang dihasilkan dari kegiatan badan publik. Pendokumentasian dilakukan secara sistematis dan terstruktur untuk memastikan informasi dapat diakses dengan mudah dan akurat.</p>\n\n                <p>Pendokumentasian informasi publik merupakan kegiatan penting dalam menjalankan amanah keterbukaan informasi publik. Dokumen yang dihasilkan dari pendokumentasian akan menjadi sumber informasi yang dapat diminta oleh masyarakat sesuai dengan ketentuan perundang-undangan.</p>\n            </div>\n        </div>\n\n        <div class=\"archive-types\">\n            <h6>Jenis Dokumen yang Didokumentasikan:</h6>\n            <ul>\n                <li>Dokumen kebijakan dan peraturan</li>\n                <li>Berita acara rapat dan pertemuan</li>\n                <li>Laporan kegiatan dan program</li>\n                <li>Data statistik dan informasi publik</li>\n                <li>Surat-menyurat resmi</li>\n                <li>Dokumen keuangan dan pengadaan</li>\n                <li>Rekaman audio visual kegiatan</li>\n                <li>Dokumen digital dan elektronik</li>\n            </ul>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Alur Prosedur Pendokumentasian</h2>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">1</div>\n                <i class=\"fas fa-file-alt\"></i>\n                <h5>Pengumpulan Dokumen</h5>\n                <p>PPID mengumpulkan semua dokumen dan informasi yang dihasilkan dari kegiatan badan publik. Pengumpulan dilakukan secara rutin dari semua unit kerja.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">2</div>\n                <i class=\"fas fa-tags\"></i>\n                <h5>Klasifikasi Dokumen</h5>\n                <p>Dokumen diklasifikasikan berdasarkan jenis, kategori, dan tingkat kerahasiaannya. Klasifikasi dilakukan sesuai dengan sistem klasifikasi yang berlaku.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">3</div>\n                <i class=\"fas fa-edit\"></i>\n                <h5>Pengolahan Dokumen</h5>\n                <p>Dokumen diproses melalui tahap identifikasi, pengindeksan, dan penomoran. Dokumen digital dipindai atau dikonversi ke format yang sesuai.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">4</div>\n                <i class=\"fas fa-archive\"></i>\n                <h5>Penyimpanan Dokumen</h5>\n                <p>Dokumen disimpan dalam sistem arsip yang aman dan terorganisir. Penyimpanan dilakukan baik dalam bentuk fisik maupun digital.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">5</div>\n                <i class=\"fas fa-search\"></i>\n                <h5>Pengelolaan Akses</h5>\n                <p>Sistem akses dokumen ditetapkan berdasarkan klasifikasi informasi. PPID mengelola hak akses untuk setiap jenis dokumen.</p>\n            </div>\n\n            <div class=\"step-card\">\n                <div class=\"step-number\">6</div>\n                <i class=\"fas fa-clock\"></i>\n                <h5>Pemeliharaan Berkala</h5>\n                <p>Dokumen dipelihara secara berkala melalui kegiatan pemindaian, pencatatan, dan pemusnahan dokumen yang sudah tidak diperlukan.</p>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Sistem Klasifikasi Dokumen</h2>\n            <div class=\"timeline\">\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">Berdasarkan Jenis</h6>\n                        <p>Dokumen diklasifikasikan berdasarkan jenis kegiatan: kebijakan, program, laporan, data, dll.</p>\n                    </div>\n                </div>\n\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">Berdasarkan Unit Kerja</h6>\n                        <p>Dokumen dikelompokkan berdasarkan unit kerja yang menghasilkan dokumen tersebut.</p>\n                    </div>\n                </div>\n\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">Berdasarkan Periode</h6>\n                        <p>Dokumen diorganisir berdasarkan tahun, bulan, atau periode waktu tertentu.</p>\n                    </div>\n                </div>\n\n                <div class=\"timeline-item\">\n                    <div class=\"timeline-content\">\n                        <h6 class=\"text-primary\">Berdasarkan Tingkat Kerahasiaan</h6>\n                        <p>Dokumen diklasifikasikan sebagai rahasia, terbatas, atau publik.</p>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"requirements-box\">\n            <h6><i class=\"fas fa-file-signature me-2\"></i>Persyaratan Dokumen</h6>\n            <ul>\n                <li>Dokumen harus lengkap dan asli</li>\n                <li>Dokumen memiliki metadata yang lengkap</li>\n                <li>Dokumen dalam kondisi baik dan terbaca</li>\n                <li>Dokumen memiliki kode klasifikasi</li>\n                <li>Dokumen disimpan dalam format yang standar</li>\n                <li>Dokumen memiliki nomor registrasi</li>\n                <li>Dokumen dilengkapi dengan tanggal pembuatan</li>\n                <li>Dokumen memiliki informasi unit pembuat</li>\n            </ul>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Sistem Penyimpanan</h2>\n            <div class=\"profil-content\">\n                <p>PPID PKTJ menggunakan sistem penyimpanan dokumen yang terintegrasi:</p>\n\n                <div class=\"row mt-4\">\n                    <div class=\"col-md-6\">\n                        <h5><i class=\"fas fa-folder-open text-primary me-2\"></i>Penyimpanan Fisik</h5>\n                        <ul>\n                            <li>Lemari arsip dengan sistem klasifikasi</li>\n                            <li>Ruang arsip yang aman dan terkontrol</li>\n                            <li>Sistem pengendalian kelembaban dan suhu</li>\n                            <li>Proteksi dari kebakaran dan banjir</li>\n                        </ul>\n                    </div>\n                    <div class=\"col-md-6\">\n                        <h5><i class=\"fas fa-server text-success me-2\"></i>Penyimpanan Digital</h5>\n                        <ul>\n                            <li>Server dengan sistem backup otomatis</li>\n                            <li>Database terintegrasi untuk metadata</li>\n                            <li>Sistem cloud storage dengan enkripsi</li>\n                            <li>Aplikasi manajemen dokumen elektronik</li>\n                        </ul>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Jangka Waktu Penyimpanan</h2>\n            <div class=\"profil-content\">\n                <p>Jangka waktu penyimpanan dokumen ditentukan berdasarkan:</p>\n                <ul>\n                    <li><strong>Dokumen Aktif:</strong> 5 tahun - dokumen yang sering diakses</li>\n                    <li><strong>Dokumen Inaktif:</strong> 10 tahun - dokumen yang jarang diakses</li>\n                    <li><strong>Dokumen Permanen:</strong> Selamanya - dokumen bersejarah penting</li>\n                    <li><strong>Dokumen Rahasia:</strong> 20 tahun atau sesuai peraturan</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Pemeliharaan dan Pemindahan</h2>\n            <div class=\"profil-content\">\n                <p>PPID melakukan pemeliharaan dokumen secara berkala:</p>\n                <ul>\n                    <li>Pembersihan dan penyusunan ulang dokumen fisik</li>\n                    <li>Verifikasi kondisi dokumen dan media penyimpanan</li>\n                    <li>Migrasi data dari media lama ke media baru</li>\n                    <li>Pembaruan sistem klasifikasi dan indeks</li>\n                    <li>Pemusnahan dokumen yang sudah tidak diperlukan</li>\n                    <li>Pembuatan laporan kondisi dokumen</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"important-note\">\n            <h6><i class=\"fas fa-exclamation-triangle me-2\"></i>PENTING</h6>\n            <p>Pendokumentasian informasi publik harus dilakukan secara akurat dan lengkap. Kesalahan dalam pendokumentasian dapat mengakibatkan kesulitan dalam mengakses informasi dan berpotensi melanggar ketentuan keterbukaan informasi publik. Semua petugas PPID wajib memahami dan melaksanakan SOP ini dengan baik.</p>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Monitoring dan Evaluasi</h2>\n            <div class=\"profil-content\">\n                <p>PPID melakukan monitoring terhadap sistem pendokumentasian melalui:</p>\n                <ul>\n                    <li>Audit berkala terhadap sistem penyimpanan</li>\n                    <li>Evaluasi efektivitas sistem klasifikasi</li>\n                    <li>Penilaian kemudahan akses dokumen</li>\n                    <li>Laporan periodik kondisi dokumentasi</li>\n                    <li>Pelatihan petugas pendokumentasian</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"content-box\">\n            <h2 class=\"section-title\">Kontak dan Informasi Tambahan</h2>\n            <div class=\"row\">\n                <div class=\"col-md-6\">\n                    <h5><i class=\"fas fa-building text-primary me-2\"></i>Kantor PPID PKTJ</h5>\n                    <p>Jl. Medan Merdeka Barat No. 8<br>\n                    Jakarta Pusat 10110<br>\n                    Indonesia</p>\n                </div>\n                <div class=\"col-md-6\">\n                    <h5><i class=\"fas fa-phone text-success me-2\"></i>Kontak</h5>\n                    <p>Telepon: (021) 3847790<br>\n                    Fax: (021) 3847791<br>\n                    Email: ppid@pktj.dephub.go.id</p>\n                </div>\n            </div>\n\n            <div class=\"mt-4\">\n                <a href=\"/layanan-informasi/daftar\" class=\"btn btn-warning me-3\">\n                    <i class=\"fas fa-list-alt me-2\"></i>Lihat Daftar Informasi Publik\n                </a>\n                <a href=\"/profil/kontak\" class=\"btn btn-outline-primary\">\n                    <i class=\"fas fa-map-marker-alt me-2\"></i>Lihat Lokasi Kantor\n                </a>\n            </div>\n        </div>\n<div class=\"premium-box-outer\" style=\"display: inline-block; width: 85%; max-width: 100%; height: 500px; margin: 20px 0; text-align: left; vertical-align: top;\">\n  <div class=\"premium-box-wrapper\" style=\"width: 100%; height: 100%; overflow: hidden; border-radius: 24px; border: 1px solid #e2e8f0; box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1); background: #ffffff;\">\n    <iframe src=\"/preview-dokumen?file=https%3A%2F%2Fdrive.google.com%2Ffile%2Fd%2F1bxbh53yoMpJbS7_pb0PeqDNmbzc3LeRi%2Fview&title=Dokumen+Informasi+Publik&is_blurred=1\" style=\"width: 100%; height: 100%; border: none;\"></iframe>\n  </div>\n</div>',NULL,'',NULL,1,NULL,NULL,'[]','2026-03-25 20:08:13','2026-03-26 00:05:26'),(14,'tugas','Tugas Pokok & Fungsi PPID PKTJ Tegal',NULL,NULL,'<p>Berdasarkan SK Direktur PKTJ dan Peraturan Menteri Perhubungan No. PM 46 Tahun 2018, PPID Pelaksana PKTJ Tegal bertugas mengoordinasikan pengumpulan, pengklasifikasian, pendokumentasian, penyimpanan, pemeliharaan, penyediaan, dan pelayanan informasi publik di lingkungan Politeknik Keselamatan Transportasi Jalan.</p>',NULL,'<div class=\"row g-4 mt-2\"><div class=\"col-md-6\"><div class=\"p-3 border rounded-3 bg-light h-100\"><h5 class=\"text-primary fw-bold mb-3\"><i class=\"fas fa-tasks me-2\"></i>Tugas Pokok</h5><ul class=\"ps-3 small\" style=\"line-height: 1.8;\"><li>Mengkoordinasikan pengumpulan seluruh informasi publik dari setiap unit kerja.</li><li>Menyimpan, mendokumentasikan, dan memelihara arsip informasi publik.</li><li>Memproses dan melayani permohonan informasi publik serta penanganan keberatan.</li><li>Melakukan pengujian konsekuensi atas informasi yang dikecualikan.</li><li>Menyusun laporan tahunan layanan informasi publik secara berkala.</li></ul></div></div><div class=\"col-md-6\"><div class=\"p-3 border rounded-3 bg-light h-100\"><h5 class=\"text-primary fw-bold mb-3\"><i class=\"fas fa-cogs me-2\"></i>Fungsi Utama</h5><ul class=\"ps-3 small\" style=\"line-height: 1.8;\"><li><strong>Fungsi Pelayanan:</strong> Memberikan layanan meja informasi dan portal elektronik yang responsif.</li><li><strong>Fungsi Verifikasi:</strong> Memvalidasi kebenaran dan klasifikasi dokumen sebelum dipublikasikan.</li><li><strong>Fungsi Pendokumentasian:</strong> Menyusun Daftar Informasi Publik (DIP) dan Daftar Informasi Dikecualikan (DIK).</li><li><strong>Fungsi Mediasi:</strong> Menyelesaikan sengketa dan keberatan permohonan informasi.</li></ul></div></div></div>',NULL,0,NULL,NULL,'[]','2026-03-25 20:27:57','2026-08-31 19:23:23'),(15,'visi','Visi dan Misi PPID PKTJ Tegal',NULL,NULL,'<h4><strong>Visi PPID PKTJ</strong></h4><p class=\"lead\"><em>\"Terwujudnya Layanan Informasi Publik Politeknik Keselamatan Transportasi Jalan yang Transparan, Cepat, Akuntabel, dan Terpercaya Menuju Tata Kelola Pendidikan Vokasi Perhubungan yang Berintegritas Tinggi.\"</em></p>',NULL,'<h4><strong>Misi PPID PKTJ</strong></h4><ol class=\"ps-3\" style=\"line-height: 1.8;\"><li><strong>Menjamin Aksesibilitas:</strong> Menjamin kemudahan dan kecepatan hak akses masyarakat terhadap informasi publik di lingkungan PKTJ Tegal secara transparan, tepat waktu, dan biaya ringan/gratis.</li><li><strong>Digitalisasi & Inklusi:</strong> Mengembangkan dan mengintegrasikan sistem layanan informasi berbasis teknologi digital yang modern, aman, serta ramah bagi penyandang disabilitas.</li><li><strong>Profesionalisme SDM:</strong> Meningkatkan kompetensi, profesionalitas, etika, dan integritas aparatur pengelola informasi dan dokumentasi secara berkelanjutan.</li><li><strong>Tata Kelola Kearsipan:</strong> Mewujudkan sistem penyimpanan, pemeliharaan, serta pendokumentasian arsip informasi kedinasan yang tertib, sistematis, dan akuntabel sesuai standar keterbukaan informasi nasional.</li></ol>',NULL,0,NULL,NULL,'[]','2026-03-25 20:27:57','2026-08-31 19:23:23'),(16,'struktur','Struktur Organisasi PPID Pelaksana PKTJ Tegal','Pejabat Pengelola Informasi dan Dokumentasi',NULL,'<p>Struktur Organisasi PPID Pelaksana Politeknik Keselamatan Transportasi Jalan (PKTJ) Tegal ditetapkan untuk menjamin efektivitas jalur komando, koordinasi, dan pembagian tugas dalam penyelenggaraan keterbukaan informasi publik.</p>',NULL,'<div class=\"p-4 bg-white border rounded-4 shadow-sm\"><h5 class=\"fw-bold text-primary mb-3\">Susunan Pejabat Pengelola Informasi dan Dokumentasi PKTJ:</h5><ul class=\"list-group list-group-flush\" style=\"line-height: 1.8;\"><li class=\"list-group-item\"><strong>1. Atasan PPID :</strong> Direktur Politeknik Keselamatan Transportasi Jalan (Bambang Istiyanto, S.SiT., M.T.)</li><li class=\"list-group-item\"><strong>2. PPID Pelaksana :</strong> Kepala Bagian Keuangan, Umum dan Kerja Sama (BAKUK)</li><li class=\"list-group-item\"><strong>3. Bidang Pengolahan Data & Klasifikasi Informasi :</strong> Bagian Administrasi Akademik dan Ketarunaan (BAAK)</li><li class=\"list-group-item\"><strong>4. Bidang Pelayanan Informasi & Dokumentasi :</strong> Subbagian Hubungan Masyarakat dan Kerja Sama</li><li class=\"list-group-item\"><strong>5. Petugas Meja Layanan (Front Office) :</strong> Pengelola Informasi Publik PKTJ Tegal</li></ul></div>','Struktur organisasi dan susunan tim kerja Pejabat Pengelola Informasi dan Dokumentasi (PPID) di lingkungan Politeknik Keselamatan Transportasi Jalan (PKTJ).',0,NULL,NULL,'[{\"title\":\"Diagram Struktur Organisasi\",\"layout\":\"diagram\",\"content\":\"<!-- Bagian ini akan dirender dengan template diagram -->\"}]','2026-03-25 20:27:57','2026-08-31 19:23:23'),(17,'regulasi','Regulasi Acuan PPID',NULL,NULL,'<p>Layanan Informasi Publik PPID PKTJ dijalankan sesuai dengan dasar-dasar hukum yang berlaku di Negara Kesatuan Republik Indonesia.<br><br>masih kurang teks editornya kurang tools rata kanan rata kirikfdujyhvgk</p>\r\n<p>&nbsp;</p>\r\n<div class=\"gdrive-preview-wrapper\" style=\"width: 100%; height: 400px; overflow: hidden; border-radius: 16px; border: 1px solid #e2e8f0; margin: 25px 0; box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1);\">\r\n<div class=\"gdrive-preview-wrapper\" style=\"width: 100%; height: 600px; overflow: hidden; border-radius: 16px; border: 1px solid #e2e8f0; margin: 25px 0; box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1);\"><iframe src=\"http://ppid.pktj.ac.id/preview-dokumen?file=https%3A%2F%2Fdrive.google.com%2Ffile%2Fd%2F1bxbh53yoMpJbS7_pb0PeqDNmbzc3LeRi%2Fview&amp;title=RANGKUM\" allowfullscreen=\"allowfullscreen\" style=\"width: 100%; height: 100%; border: none;\"></iframe><iframe src=\"/preview-dokumen?file=https%3A%2F%2Fdrive.google.com%2Ffile%2Fd%2F1bxbh53yoMpJbS7_pb0PeqDNmbzc3LeRi%2Fview&amp;title=Dokumen+Informasi+Publik&amp;is_blurred=1\" style=\"width: 100%; height: 100%; border: none;\"></iframe></div>\r\n</div>',NULL,NULL,NULL,1,NULL,NULL,'[]','2026-03-25 20:27:57','2026-05-20 16:12:47'),(18,'kontak','Hubungi Kami','Hubungi Kami Untuk Informasi Lebih Lanjut',NULL,'<p>Kami siap membantu Anda terkait permintaan informasi publik, pengajuan keberatan, dan panduan regulasi. Jangan ragu menghubungi PPID PKTJ.<br><br><br><br>08999999guuy</p>\r\n<p>🔢</p>\r\n<p><img style=\"max-width: 100%; height: 500px;\" src=\"http://ppid.pktj.ac.id/storage/editor_uploads/1779327300_6a0e61448f07f.jpg\" alt=\"253468285270156645.jpg\" width=\"333\"></p>',NULL,NULL,NULL,1,NULL,NULL,'[{\"title\":\"hjvhjkuigi\",\"content\":\"<p>uogiugduxszage<\\/p>\\r\\n<p>hvbjhsgcsbcygsdj<\\/p>\\r\\n<p><img src=\\\"http:\\/\\/ppid.pktj.ac.id\\/storage\\/keberatan\\/ktp\\/1777861214_ktp_16_20251025_061122_0015.png\\\" alt=\\\"\\\" width=\\\"300\\\" height=\\\"400\\\"><\\/p>\",\"layout\":\"cards\"}]','2026-03-25 20:27:57','2026-05-20 18:35:37');
