/*!40000 ALTER TABLE `profils` DISABLE KEYS */;
INSERT INTO `profils` VALUES (1,'profil','Profil PPID','<div style=\"text-align: justify;\"><span style=\"background-color: rgb(255 255 255 / var(--tw-bg-opacity, 1));\">Dalam mewujudkan tata kelola pemerintahan yang baik di lingkungan Politeknik Keselamatan Transportasi Jalan&nbsp;melalui informasi publik guna memenuhi hak pemohon informasi sesuai dengan ketentuan peraturan perundang-undangan.</span><br></div><p></p><div style=\"text-align: justify;\"><span style=\"background-color: var(--color-white);\">Sejak Undang-Undang Nomor 14 Tahun 2008 Tentang Keterbukaan Informasi Publik (UU KIP) diberlakukan secara efektif pada tanggal 30 April 2010 telah mendorong bangsa Indonesia satu langkah maju ke depan, menjadi bangsa yang transparan dan akuntabel dalam mengelola sumber daya publik. UU KIP sebagai instrumen hukum yang mengikat merupakan tonggak atau dasar bagi seluruh rakyat Indonesia untuk bersama-sama mengawasi secara langsung pelayanan publik yang diselenggarakan oleh Badan Publik.</span></div><div style=\"text-align: justify;\"><span style=\"background-color: var(--color-white);\">Keterbukaan informasi adalah salah satu pilar penting yang akan mendorong terciptanya iklim transparansi. Terlebih di era yang serba terbuka ini, keinginan masyarakat untuk memperoleh informasi semakin tinggi. Diberlakukannya UU KIP merupakan perubahan yang mendasar dalam kehidupan bermasyarakat, berbangsa dan bernegara, oleh sebab itu perlu adanya kesadaran dari seluruh elemen bangsa agar setiap lembaga dan badan pemerintah dalam pengelolaan informasi harus dengan prinsip good governance, tata kelola yang baik dan akuntabilitas.</span></div><div style=\"text-align: justify;\"><span style=\"background-color: var(--color-white);\">Sejalan dengan amanah Undang-Undang Nomor 14 Tahun 2008 tentang Keterbukaan Informasi Publik, Kementerian Perhubungan telah membentukan Pejabat Pengelola Informasi dan Dokumentasi (PPID) dan Pedoman pelaksanaan layanan informasi publik&nbsp; yang ditetapkan melalui Peraturan Menteri Perhubungan Nomor PM. 46 Tahun 2018 Tentang Pedoman Pengelolaan Informasi dan Dokumentasi di lingkungan Kementerian Perhubungan.</span></div><p></p>',NULL,1,1,'2026-03-03 00:23:06','2026-03-08 20:51:47'),(2,'tugas','Tugas dan Tanggung Jawab PPID','<p style=\"text-align: justify; margin-bottom: 15px;\">Sesuai dengan Peraturan Menteri perhubungan Nomor PM.46 Tahun 2018 tentang Pedoman Pengelolaan Informasi dan Dokumentasi di Lingkungan Kementerian Perhubungan, PPID PKTJ Tegal selaku PPID Pelaksana UPT memiliki tanggung jawab, yakni :</p><ol style=\"margin-bottom: 15px; padding-left: 50px; text-align: justify;\"><li style=\"\">Melakukan pengelolaan informasi publik;</li><li style=\"\">Menyampaikan informasi secara baik dan efisien sehingga dapat diakses dengan mudah;</li><li style=\"\">Melakukan pemutakhiran dalam pengelolaan maupun pengembangan digital;</li><li style=\"\">Menyediakan sarana dan prasarana dalam pelaksanaan pelayanan informasi.</li></ol>',NULL,1,1,'2026-03-04 07:34:38','2026-03-04 00:51:44'),(3,'visi','Visi dan Misi PPID','<p><strong>Visi PPID PKTJ</strong></p><p>Menjadi PPID yang terdepan dalam pelayanan informasi publik yang transparan dan akuntabel.</p><p><strong>Misi PPID PKTJ</strong></p><ul><li>Menyediakan informasi publik yang berkualitas;</li><li>Memastikan akses informasi yang mudah dan cepat;</li><li>Meningkatkan transparansi dan akuntabilitas;</li><li>Melayani permohonan informasi dengan profesional.</li></ul>',NULL,1,1,'2026-03-04 07:38:04','2026-03-04 07:38:04'),(4,'struktur','Struktur Organisasi','<p><strong>Struktur Organisasi PPID PKTJ</strong></p><p>PPID PKTJ dipimpin oleh Kepala PPID yang dibantu oleh:</p><ul><li>Kepala Sub Bagian Informasi;</li><li>Staf Administrasi Informasi;</li><li>Petugas Pelayanan Informasi;</li><li>Staf Teknis Informasi.</li></ul>',NULL,1,1,'2026-03-04 07:38:04','2026-03-04 07:38:04'),(5,'regulasi','Regulasi','<p><strong>Regulasi PPID PKTJ</strong></p><p>PPID PKTJ mengacu pada regulasi berikut:</p><ul><li>UU No. 14 Tahun 2008 tentang Keterbukaan Informasi Publik;</li><li>Peraturan Komisi Informasi No. 1 Tahun 2010;</li><li>Peraturan Internal PKTJ tentang PPID.</li></ul>',NULL,1,1,'2026-03-04 07:38:04','2026-03-04 07:38:04'),(6,'kontak','Kontak','<p><strong>Kontak PPID PKTJ</strong></p><p>Untuk informasi lebih lanjut, hubungi:</p><ul><li>Alamat: Jl. Pendidikan No. 123, Kota</li><li>Telepon: (021) 1234-5678</li><li>Email: ppid@pktj.ac.id</li><li>Website: www.ppid.pktj.ac.id</li></ul>',NULL,1,1,'2026-03-04 07:38:04','2026-03-04 07:38:04');
/*!40000 ALTER TABLE `profils` ENABLE KEYS */;
UNLOCK TABLES;

